window.REVISION_SUBJECTS.push({"config":{"brandIcon":"🪯","brandSubtitle":"AQA GCSE Religious Studies A (8062)","brandTitle":"Sikhism (AQA RS A)","breadcrumb":"Religious Studies / AQA A / Sikhism","examBoard":"AQA GCSE","footerNote":"Original practice questions written to the AQA GCSE Religious Studies A (8062) specification, using the five-part question pattern (1, 1, 4, 6 and 12 marks) that applies from summer 2026. Not past-paper material. Model answers are indicative exemplars, not official AQA mark schemes; other valid answers are credited.","heroEyebrow":"Component 1 · Sikhism · Beliefs \u0026 teachings · Practices","markingSchemaId":"aqa-rs-generic","pageTitle":"AQA GCSE Religious Studies A: Sikhism Revision","papers":[{"id":"Beliefs","label":"Beliefs \u0026 teachings","subtitle":"Key beliefs · the nature of human life (spec 3.1.7.1)","title":"Sikhism: Beliefs and teachings"},{"id":"Practices","label":"Practices","subtitle":"Worship and service · festivals and lifestyle (spec 3.1.7.2)","title":"Sikhism: Practices"}],"storageId":"aqa_rs_a_sikhism","subjectArea":"Religious Studies","subjectName":"Sikhism"},"questions":{"paper1":[{"id":"aqa-rs-a-sikhism-paper1-1-1-0","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Which one of the following words in the Mool Mantra means 'without fear'?\nA Nirvair\nB Nirbhau\nC Ajuni\nD Saibhang","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – Nirbhau. 'Nir' means 'without' and 'bhau' means 'fear'. Nirvair means without hatred/enmity, Ajuni means beyond birth (not born into any life form) and Saibhang means self-existent.","evidence":["Mool Mantra, Guru Granth Sahib Ang 1"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"mool mantra terms"},{"id":"aqa-rs-a-sikhism-paper1-1-1-1","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Where is the Mool Mantra found in the Guru Granth Sahib?\nA At the start of the Japji Sahib on Ang 1\nB In the Rehras Sahib on Ang 8\nC In the Kirtan Sohila on Ang 12\nD In the Saloks of Guru Tegh Bahadur near the end","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A – At the start of the Japji Sahib on Ang 1. The Mool Mantra is the opening statement of the Guru Granth Sahib and stands at the head of Guru Nanak's Japji Sahib. It is also repeated (in full or short form) at the start of many later sections.","evidence":["Guru Granth Sahib Ang 1 (Japji Sahib)"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"mool mantra location"},{"id":"aqa-rs-a-sikhism-paper1-1-1-2","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Give one quality of God described in the Mool Mantra.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: God is One (Ik Onkar); God's name is Truth (Satnam); God is the Creator (Karta Purakh); God is without fear (Nirbhau); God is without hatred (Nirvair); God is timeless/immortal (Akal Murat); God is beyond birth and death (Ajuni); God is self-existent (Saibhang); God is known by the Guru's grace (Gurprasad).","evidence":["Mool Mantra, Ang 1"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"qualities of God"},{"id":"aqa-rs-a-sikhism-paper1-1-1-3","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Give one meaning of the term 'Gurprasad' in the Mool Mantra.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"God is known/realised through the Guru's grace (God's grace is needed to understand God).","evidence":["Mool Mantra, Ang 1"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"gurprasad"},{"id":"aqa-rs-a-sikhism-paper1-1-1-4","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Explain two ways in which the belief that God is One (Ik Onkar) influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Ik Onkar teaches that there is only one God who created and is present in all people, Sikhs treat everyone as equal. This influences them to welcome people of every religion, caste and gender into the gurdwara and to sit them side by side in the langar.\n\nSecond way: The Ik Onkar symbol reminds Sikhs that their whole life should be centred on the One God. Many Sikhs display it in their homes and gurdwaras and begin the day by reciting the Mool Mantra in Japji Sahib, so that every activity, including work and family life, is done with God in mind.","evidence":["Ik Onkar – the first words of the Mool Mantra, Ang 1","Langar and equality","Nitnem – Japji Sahib"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"ik onkar influence"},{"id":"aqa-rs-a-sikhism-paper1-1-1-5","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Explain two ways in which the Mool Mantra is important in the daily life of Sikhs.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: It is recited every morning as the opening of Japji Sahib in Nitnem. This means Sikhs start the day by remembering what God is like – true, fearless, without hatred – which focuses their mind on God before work begins.\n\nSecond way: It is used at key life events. For example, at the Amrit Sanskar the Panj Pyare recite the Mool Mantra and the initiate repeats it, and some families whisper it to a newborn baby. This shows the Mool Mantra marks belonging to the Sikh community and the start of a God-centred life.","evidence":["Nitnem","Amrit Sanskar","Birth rites"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"mool mantra use"},{"id":"aqa-rs-a-sikhism-paper1-1-1-6","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Explain two Sikh teachings about the nature of God as expressed in the Mool Mantra.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: God is One and is the Creator (Ik Onkar, Karta Purakh). There is only one God, not many gods, and everything in the universe comes from this one source. This means all people and all creation share the same origin, so no group is closer to God by birth.\n\nSecond teaching: God is eternal and beyond birth (Akal Murat, Ajuni, Saibhang). God is not born, does not die and depends on nothing else, so Sikhs reject the idea that God takes human form as an avatar. God can be known only through grace (Gurprasad), not by human effort alone.\n\nSource: The Mool Mantra on Ang 1 of the Guru Granth Sahib begins 'Ik Onkar, Satnam, Karta Purakh…' and ends 'Gurprasad'. The lines after it – 'True in the beginning, true throughout the ages, true now… and forever true' – show that God's nature never changes, which supports the teaching that God is eternal.","evidence":["Mool Mantra, Ang 1","'Aad sach, jugaad sach, hai bhi sach, Nanak hosi bhi sach' – Ang 1","Rejection of avatars"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"nature of God"},{"id":"aqa-rs-a-sikhism-paper1-1-1-7","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"Explain two reasons why the Mool Mantra is significant for Sikhs.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First reason: It sums up Sikh belief about God in a few words. Tradition holds it was the first teaching of Guru Nanak after his experience at the river Bein, so Sikhs see it as the foundation (mool = root) of all the Guru's teaching that follows in the scripture.\n\nSecond reason: It is used for meditation and worship. Repeating the Mool Mantra (and the name Waheguru) is a form of nam japna, which helps Sikhs remember God and overcome haumai (ego), moving them towards mukti.\n\nSource: The Mool Mantra opens the Guru Granth Sahib on Ang 1 and a shortened form is repeated at the start of many sections, which shows how central it is. Its final word 'Gurprasad' teaches that God is known by grace, so Sikhs recite it humbly, asking for that grace.","evidence":["Guru Granth Sahib Ang 1","Guru Nanak at the river Bein (c.1499)","Nam japna"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"significance of mool mantra"},{"id":"aqa-rs-a-sikhism-paper1-1-1-8","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"“The Mool Mantra tells Sikhs everything they need to know about God.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nThe Mool Mantra is the first composition in the Guru Granth Sahib (Ang 1) and its name means 'root' teaching. Sikhs believe Guru Nanak received it after his experience of God at the river Bein, so it is revelation. Many Sikhs argue that everything later in the scripture is an expansion of this root, so in principle it contains everything essential.\n\nIt covers the most important qualities of God in a carefully ordered way: God is One (Ik Onkar), Truth (Satnam), the Creator (Karta Purakh), without fear or hatred (Nirbhau, Nirvair), timeless, unborn and self-existent (Akal Murat, Ajuni, Saibhang). A Sikh who meditates on these words learns how to relate to God and how to live – fearlessly, without hatred and truthfully.\n\nIt also tells Sikhs how God is known: 'Gurprasad' – by the Guru's grace. So it does not just describe God but shows the path to God, which is arguably the most important thing a believer needs.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nThe Mool Mantra is very short. It tells Sikhs what God is like, but it does not explain how to escape haumai, what the five khands are, or how to live as gurmukh. These are found in Japji Sahib and the rest of the 1,430 Angs of the Guru Granth Sahib, so Sikhs need the whole scripture, not just its opening.\n\nMany words in the Mool Mantra are negative (without fear, without hatred, beyond birth). They tell Sikhs what God is not rather than giving a full description, which suggests God is ultimately beyond words. The Japji itself says that God cannot be understood by thinking, even if one thinks a hundred thousand times (Ang 1). So no text could tell 'everything' about God.\n\nSikhs also believe God is experienced, not just known about. Nam japna, sewa and the sangat give an inner experience of God that words cannot replace. A humanist would add that the Mool Mantra makes claims that cannot be tested, so it cannot tell anyone 'everything' about a being whose existence is not proven.\n\nCONCLUSION\n\nThe Mool Mantra gives Sikhs everything essential about God in summary form, which is why it is called the root. However, 'everything they need to know' is too strong: Sikh teaching itself says God is beyond full human understanding and must be experienced through grace, meditation and service. The stronger view is that the Mool Mantra is the indispensable foundation, but not the whole building.","evidence":["Mool Mantra, Ang 1","'Sochai soch na hovaee' – Japji, Ang 1","Japji Sahib and the five khands","Gurprasad – grace","Humanist view"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"mool mantra evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-1-9","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God as expressed in the Mool Mantra","question":"“Ik Onkar is the most important belief in Sikhism.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nIk Onkar ('There is one God') are the first words of the Mool Mantra and of the whole Guru Granth Sahib (Ang 1). Their position shows that every other teaching depends on them. If God were not One, the other qualities in the Mool Mantra – Creator, Truth, without hatred – would not make sense.\n\nBelief in one God underpins Sikh ethics. Because the One God created everyone and is present in everyone ('Among all is the Light, and You are that Light' – Ang 13), Sikhs believe in the equality of all people, expressed in langar, sangat and the rejection of caste. So Ik Onkar is the source of Sikh social teaching as well as belief.\n\nIt is also the basis of worship. Nam japna is meditation on the Name of the one God, and the goal of life, mukti, is union with the One. Without Ik Onkar there would be no aim to Sikh life at all.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nSome Sikhs would say that knowing God is One is not enough – what matters is how a person lives. Guru Nanak taught that 'Truth is higher than everything, but higher still is truthful living' (Ang 62). On this view, sewa, honest work (kirat karna) and sharing (vand chhakna) are just as important, because belief without action does not lead to mukti.\n\nOthers might argue that belief in the Guru – God's grace through the Gurus and the authority of the Guru Granth Sahib as the living Guru – is the most distinctive Sikh belief. Many religions believe in one God, but belief in the ten Gurus and the Guru Granth Sahib is what makes Sikhism distinct.\n\nOthers might stress becoming gurmukh and overcoming haumai, since this is what Sikhs actually struggle with every day. A non-religious person might argue that the most valuable parts of Sikhism are its ethical values – equality and service – which can be admired without believing in God at all.\n\nCONCLUSION\n\nAlthough sewa, the Guru and the struggle against haumai are vital, each only makes sense because of Ik Onkar: equality comes from one Creator, the Guru reveals the one God, and haumai is overcome by remembering the one God's Name. So Ik Onkar is best seen as the most important belief because it is the foundation of all the others, even though Sikhs insist it must be lived out, not just believed.","evidence":["Ik Onkar – Ang 1","'Sabh meh jot jot hai soi' – Ang 13","'Sachahu orai sabh ko upar sach aachaar' – Ang 62","Gurprasad","Kirat karna, vand chhakna, nam japna"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"ik onkar evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-2-0","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Which one of the following Punjabi words refers to God's creation or the natural world?\nA Kudrat\nB Haumai\nC Hukam\nD Mukti","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A – Kudrat. Kudrat means nature/creation, in which God's creative power is seen. Haumai is ego, hukam is God's will or command, and mukti is liberation.","evidence":["Asa di Var, Ang 469 – 'Balihari kudrat vasia'"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"kudrat"},{"id":"aqa-rs-a-sikhism-paper1-1-2-1","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Which one of the following best describes the Sikh belief that God is both within creation and beyond it?\nA God is only found in the gurdwara\nB God is immanent and transcendent\nC God created the world and then left it alone\nD God is identical to the physical universe and nothing more","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – God is immanent and transcendent. Sikhs believe God is present in and through the universe (sargun) and also separate from and greater than it (nirgun). C and D each describe only half of this belief, and A wrongly limits God to one place.","evidence":["Sargun and nirgun","Ang 13","Ang 1035"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"immanent and transcendent"},{"id":"aqa-rs-a-sikhism-paper1-1-2-2","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Give one Sikh belief about how God created the universe.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: God created by a single word/command (hukam) – 'You created the vast expanse with One Word' (Japji, Ang 3); before creation there was only darkness and God alone in deep meditation (Ang 1035); God created out of God's own will; creation came from God, not from pre-existing matter.","evidence":["Japji pauri 16, Ang 3","Maru Solhe, Ang 1035"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"creation"},{"id":"aqa-rs-a-sikhism-paper1-1-2-3","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Give one meaning of the term 'nirgun'.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"God without attributes/qualities – God as transcendent, beyond and separate from creation and beyond human understanding.","evidence":["Nirgun / sargun"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"nirgun"},{"id":"aqa-rs-a-sikhism-paper1-1-2-4","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Explain two ways in which the belief that God is present in creation influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs respect and care for the environment. Because God's light is in all of nature (kudrat), harming the earth is seen as disrespecting God. For example, the EcoSikh movement encourages gurdwaras to plant trees and reduce waste, and Sikhs mark Sikh Environment Day each March.\n\nSecond way: Sikhs respect all people. If God is present in every person, then every human deserves dignity, whatever their religion, caste or gender. This leads Sikhs to serve everyone in the langar and to see sewa to others as serving God.","evidence":["Ang 13 – 'Sabh meh jot jot hai soi'","EcoSikh / Sikh Environment Day","Langar"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"god in creation influence"},{"id":"aqa-rs-a-sikhism-paper1-1-2-5","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Explain two ways in which belief in God as Creator influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: It makes Sikhs humble and grateful. Since everything they have – life, family, wealth – was created and given by God, Sikhs thank God in daily prayer (for example in Ardas) and try not to become proud, which helps them overcome haumai.\n\nSecond way: It encourages Sikhs to accept God's will (hukam). If God created and sustains everything, then events in life happen within God's order. Many Sikhs try to respond calmly to difficulties, echoing Guru Arjan's words 'Tera keea meetha laagai' ('Your actions seem sweet to me'), rather than blaming God.","evidence":["Karta Purakh – Ang 1","Hukam – Japji pauri 2, Ang 1","'Tera keea meetha laagai' – Ang 394 (Guru Arjan)"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"creator influence"},{"id":"aqa-rs-a-sikhism-paper1-1-2-6","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Explain two Sikh teachings about God's relationship with creation.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: God is shown in and through the universe (immanent, sargun). God's light is in every part of creation and in every person, so the world itself reveals God. Sikhs may say they see God's hand in the beauty and order of nature.\n\nSecond teaching: God is also separate from the universe (transcendent, nirgun). God existed before creation, in deep meditation in the void, and is not limited by space or time. God is beyond the universe and cannot be fully described by any created thing.\n\nSource: In Asa di Var Guru Nanak writes 'I am a sacrifice to Your creation; You are pervading it' (Ang 469), showing God is in creation. The Maru Solhe hymn on Ang 1035 says that for countless ages there was only darkness and God alone, showing God existed independently before and apart from creation.","evidence":["'Balihari kudrat vasia' – Ang 469","'Arbad narbad dhundhukara' – Ang 1035","Sargun and nirgun"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"god and creation"},{"id":"aqa-rs-a-sikhism-paper1-1-2-7","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"Explain two Sikh beliefs about the creation of the universe.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First belief: The universe was created by God's word or command (hukam). God did not need materials or helpers; the whole universe came into existence because God willed it. This shows God's total power as Karta Purakh.\n\nSecond belief: Before creation there was only God in a state of formless meditation, with no earth, sky, day or night. God then chose to create, and creation is continuous – God sustains it at every moment and can draw it back again. This is compatible, for many Sikhs, with scientific ideas such as the Big Bang.\n\nSource: Japji Sahib, pauri 16 (Ang 3) says 'You created the vast expanse of the universe with One Word', applying the idea that creation came from God's command. Guru Nanak's Maru Solhe (Ang 1035) describes the darkness before creation, when there was only God's command (hukam).","evidence":["Japji pauri 16, Ang 3 – 'Keeta pasao eko kavao'","Ang 1035","Big Bang compatibility"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"creation"},{"id":"aqa-rs-a-sikhism-paper1-1-2-8","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"“God is easier to find in nature than in a gurdwara.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nSikhs believe God is shown in and through the universe. Guru Nanak praised God's presence in kudrat (creation) – 'I am a sacrifice to Your creation; You are pervading it' (Ang 469). A sunrise, a mountain or a living creature can make a person aware of God's power and beauty directly, without any building.\n\nThe Guru Granth Sahib often uses images of nature – rivers, the ocean, the lotus, the moth and flame – to describe God. Guru Nanak himself travelled widely (the udasis) and taught in open places as well as homes. His hymn 'Gagan mai thaal' (Ang 13) describes the whole universe as a natural arti (worship) to God, suggesting nature itself worships God.\n\nSome people find buildings and rituals distracting or divisive, and feel closer to God when alone in nature. Many non-religious people also say nature gives them a sense of awe, even if they do not call it God.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nGod is also transcendent (nirgun) – beyond nature. Nature shows God's creation, but not God's full reality, and enjoying nature can become maya (illusion) and attachment if it is not linked to remembering God's Name. Sikhs believe God is found through the Guru's grace (Gurprasad), and the Guru today is the Guru Granth Sahib, which is housed in the gurdwara.\n\nIn the gurdwara Sikhs hear gurbani and kirtan, join the sangat and take part in langar. The Guru Granth Sahib says the true company (satsangat) is where the One Name is spoken (Ang 72). The sangat supports people to become gurmukh, which is harder alone in nature.\n\nSikhs also teach that God is found within, by meditating on the Name (nam japna). The place matters less than the state of the mind: someone can walk in a forest full of haumai, or sit in a gurdwara and be truly focused on God.\n\nCONCLUSION\n\nNature certainly reveals God for Sikhs, because God pervades creation. But Sikhism teaches that God is most fully known through the Guru's word and the Name, which the gurdwara makes available through the Guru Granth Sahib and the sangat. So it is not 'easier' to find God in nature; rather, nature and the gurdwara work together, and for Sikhs the deciding factor is an inward, God-centred mind.","evidence":["'Balihari kudrat vasia' – Ang 469","'Gagan mai thaal' – Ang 13","'Satsangat kaisee jaaneeai' – Ang 72","Sargun and nirgun","Maya"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"god in nature"},{"id":"aqa-rs-a-sikhism-paper1-1-2-9","paper":"Beliefs","module":"1.2","moduleTitle":"God as Creator: God in and through the universe, and separate from it","question":"“Science has replaced the need for a Creator God.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nMany atheists and humanists argue that science gives a complete explanation of how the universe came about. The Big Bang theory explains the origin of the universe around 13.8 billion years ago and evolution explains the development of life, so there is no need to bring in God as Karta Purakh.\n\nScientific explanations are based on evidence that can be tested, whereas religious beliefs about creation rely on revelation. On this view, belief in a Creator was useful before people understood nature, but is now unnecessary.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMost Sikhs see no conflict between science and the Guru Granth Sahib. The scripture describes a vast universe with 'hundreds of thousands of nether worlds and skies' (Japji pauri 22, Ang 5) and countless galaxies, which many Sikhs say fits modern astronomy. Guru Nanak's description of a time of only darkness before creation (Ang 1035) is often compared to the state before the Big Bang.\n\nSikhs believe God created by a single command: 'You created the vast expanse with One Word' (Ang 3). Science explains how the universe developed, but Sikhs argue it cannot explain why there is anything at all, or why the universe has order. God's hukam is the reason behind the laws that science describes.\n\nSikhs also believe the purpose of creation is spiritual – human life is a chance to unite with God (Ang 12). Science does not answer questions of meaning or purpose, so the need for God remains. The Guru Granth Sahib even says that only the Creator knows when creation happened (Japji pauri 21, Ang 4), showing humility about how much humans can know.\n\nCONCLUSION\n\nScience has replaced some older literal ideas about how the world began, but it has not replaced the need for a Creator for those who ask why the universe exists and what life is for. Sikhism is well placed here, because its scripture already describes an immense, evolving universe ruled by God's order. The stronger view is that science and belief in a Creator answer different questions, so science has not removed the need for God.","evidence":["Japji pauri 16, Ang 3","Japji pauri 21–22, Ang 4–5","Ang 1035","Ang 12 – human life an opportunity","Big Bang / evolution","Humanist view"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"science and creation"},{"id":"aqa-rs-a-sikhism-paper1-1-3-0","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Which one of the following Sikh virtues means contentment?\nA Nimrata\nB Santokh\nC Daya\nD Sat","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – Santokh. Santokh is contentment: being satisfied with what God has given rather than greedy. Nimrata is humility, daya is compassion, and sat is truth.","evidence":["The five virtues: sat, santokh, daya, nimrata, pyare"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"virtues"},{"id":"aqa-rs-a-sikhism-paper1-1-3-1","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Which one of the following best describes the Sikh belief about human life?\nA It is a punishment for sins in a past life\nB It is the only life a person will ever have\nC It is a precious opportunity to unite with God\nD It is an illusion with no value","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C – It is a precious opportunity to unite with God. Sikhs believe the soul passes through many life forms, and that the human birth is rare and is the chance to become one with God: 'This human body has been given to you; this is your chance to meet the Lord of the Universe' (Ang 12).","evidence":["'Bhaee paraapat maanukh dehureeaa' – Ang 12"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"human life"},{"id":"aqa-rs-a-sikhism-paper1-1-3-2","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Give one Sikh virtue.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: wisdom (gian); truthful living (sat/sach aachaar); justice (niaon); temperance; self-control; patience (sabr/dhiraj); courage (nirbhau/bravery); humility (nimrata); contentment (santokh); compassion (daya); love (pyare).","evidence":["AQA spec list of Sikh virtues"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"virtues"},{"id":"aqa-rs-a-sikhism-paper1-1-3-3","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Give one reason why Sikhs believe human life is special.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: only in human life can the soul unite with God/achieve mukti; human birth is rare, coming after many lives in other forms; humans can recognise God's light within and choose to remember God's Name; humans have the ability to develop virtues.","evidence":["Ang 12","Karma and rebirth"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"human life"},{"id":"aqa-rs-a-sikhism-paper1-1-3-4","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Explain two ways in which belief that human life is an opportunity to unite with God influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs try not to waste their time on earth. Because the human birth is rare and precious, many Sikhs rise early at amrit vela to meditate on God's Name and recite Nitnem, so that every day brings them closer to God.\n\nSecond way: Sikhs try to develop virtues and live morally. Since union with God depends on overcoming haumai, Sikhs work at virtues such as humility and patience, for example by doing sewa such as cleaning shoes at the gurdwara, which trains them to put others before themselves.","evidence":["Ang 12","Amrit vela","Sewa"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"human life influence"},{"id":"aqa-rs-a-sikhism-paper1-1-3-5","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Explain two ways in which the virtue of truthful living influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs aim to earn their living honestly (kirat karna). This means a Sikh in business would refuse to cheat customers or take bribes, because how they earn money is as important as how much they earn.\n\nSecond way: Sikhs try to make their words and actions match their beliefs. Guru Nanak taught that truthful living is higher than knowing the truth, so a Sikh should not just attend the gurdwara but also treat family, colleagues and strangers fairly and kindly in everyday life.","evidence":["'Sachahu orai sabh ko upar sach aachaar' – Ang 62","Kirat karna"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"truthful living"},{"id":"aqa-rs-a-sikhism-paper1-1-3-6","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Explain two Sikh virtues that help a person move closer to God.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First virtue: Humility (nimrata). Humility is the opposite of haumai (ego), which is the main barrier between a person and God. A humble person does not think they are better than others, accepts God's will and is willing to serve, for example by washing dishes in the langar.\n\nSecond virtue: Contentment (santokh). A contented person is satisfied with what God has given and is free from greed (lobh), one of the five thieves. Contentment brings inner peace, which makes it easier to focus the mind on God's Name.\n\nSource: The Guru Granth Sahib praises humility: 'Sweetness and humility are the essence of goodness and virtue' ('Mithat neevee Nanaka gun changiaaeeaa tat' – Ang 470). This shows that humility is not a weakness but the heart of a God-centred life, so it helps the Sikh move towards mukti.","evidence":["'Mithat neevee Nanaka gun changiaaeeaa tat' – Ang 470","Five thieves","Haumai"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"virtues"},{"id":"aqa-rs-a-sikhism-paper1-1-3-7","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"Explain two Sikh teachings about the nature of human life.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Human life is a rare opportunity to unite with God. The soul (atma) has passed through many life forms according to karma, and only as a human can it consciously remember God and achieve mukti. So life should not be wasted on selfish pleasures.\n\nSecond teaching: Every human contains God's divine light (jot). This means each person has the potential to become gurmukh and develop virtues such as wisdom, justice and courage. It also means all humans are equal and must be treated with respect.\n\nSource: In the Sohila, Guru Arjan writes: 'This human body has been given to you. This is your chance to meet the Lord of the Universe. Nothing else will work' (Ang 12). Sikhs apply this by focusing on nam japna and sewa rather than wealth or status.","evidence":["'Bhaee paraapat maanukh dehureeaa, gobind milan kee eh teree bareeaa' – Ang 12","Jot – Ang 13"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"human life"},{"id":"aqa-rs-a-sikhism-paper1-1-3-8","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"“Being humble is the most important Sikh virtue.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nFor Sikhs the greatest barrier to union with God is haumai – ego or self-centredness. Humility (nimrata) is the direct opposite of haumai, so it could be seen as the virtue that unlocks all the others. Guru Nanak wrote that 'sweetness and humility are the essence of goodness and virtue' (Ang 470).\n\nHumility is built into Sikh practice. Everyone covers their head and removes shoes in the gurdwara, bows before the Guru Granth Sahib and sits on the floor at the same level in the langar. Sewa such as cleaning shoes or washing dishes is valued precisely because it teaches humility. The Gurus themselves modelled it – Guru Amar Das served in the langar of Guru Angad before he became Guru.\n\nA person without humility may be truthful, brave or wise, but use those qualities to feel proud, which leads them away from God. So humility protects the other virtues.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nGuru Nanak taught that 'Truth is higher than everything, but higher still is truthful living' (Ang 62). Many Sikhs would therefore say truthful living (sach aachaar) is the most important, because it includes all the virtues in action. Humility without honesty would not be enough.\n\nOthers would argue that courage and justice are central, especially in Sikh history. Guru Gobind Singh created the Khalsa to defend the oppressed and the Gurus Arjan and Tegh Bahadur accepted martyrdom rather than give up their principles. A purely humble person might not stand up against injustice, which Sikhs are required to do.\n\nIt can also be argued that Sikhism does not rank virtues at all: virtues such as wisdom, contentment, patience, self-control and compassion work together, and a gurmukh shows them all. Non-religious people might value compassion or justice above humility, seeing too much humility as allowing others to be treated unfairly.\n\nCONCLUSION\n\nHumility has a strong claim, because it directly attacks haumai, the root problem in Sikh teaching. However, Sikh history shows that humility must be balanced by courage and justice, and Guru Nanak's emphasis on truthful living suggests all virtues must be lived together. The best conclusion is that humility is the foundation of the Sikh virtues, but not sufficient on its own.","evidence":["'Mithat neevee Nanaka' – Ang 470","'Sach aachaar' – Ang 62","Guru Amar Das's sewa","Khalsa and martyrdom of Gurus","Haumai"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"humility evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-3-9","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","question":"“Developing virtues is more important than worship for Sikhs.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nGuru Nanak repeatedly criticised empty ritual. He taught that 'Truth is higher than everything, but higher still is truthful living' (Ang 62). On this view, a Sikh who attends the gurdwara but cheats in business has missed the point; virtues such as honesty, justice and compassion are what God values.\n\nThe aim of human life is to unite with God, and the barrier is haumai and the five thieves (lust, anger, greed, attachment and pride). These are overcome by developing their opposite virtues – self-control, patience, contentment and humility. So virtue is the actual path to mukti.\n\nVirtues also benefit others: the Sikh emphasis on equality and sewa means a virtuous life helps society, while worship might seem more private. A humanist would agree that good character matters more than religious ritual.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nFor Sikhs virtues are not developed by willpower alone. They grow through nam japna – meditation on God's Name – and the Guru's grace (Gurprasad). Guru Ram Das describes the true Sikh as one who rises early and meditates on the Name (Ang 305). Without this worship, virtues may themselves become a source of pride.\n\nWorship in the sangat, listening to kirtan and reading the Guru Granth Sahib give Sikhs the teaching and inspiration they need to be virtuous. The Guru Granth Sahib says the Name is found in the satsangat (Ang 72). So worship and virtue cannot be separated: worship is the root and virtue the fruit.\n\nAlso, many Sikhs see worship as the expression of love for God, which is the deepest purpose of human life. Doing good deeds while forgetting God would leave a person manmukh rather than gurmukh.\n\nCONCLUSION\n\nSikhism rejects worship that is only ritual, so virtue is clearly essential. But it equally rejects the idea that a person can become good without remembering God. The three pillars – nam japna, kirat karna and vand chhakna – show that worship and virtuous living are equally necessary, so the statement is too one-sided: for Sikhs virtues are developed through worship, not instead of it.","evidence":["'Sach aachaar' – Ang 62","Ang 305 – the Gursikh's daily routine","Ang 72 – satsangat","Five thieves","Three pillars"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"virtues vs worship"},{"id":"aqa-rs-a-sikhism-paper1-1-4-0","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Which one of the following is the Sikh term for liberation from the cycle of rebirth and union with God?\nA Mukti\nB Maya\nC Manmukh\nD Moh","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A – Mukti. Mukti means liberation: freedom from the cycle of birth, death and rebirth and union with God. Maya is illusion, manmukh means self-centred, and moh is worldly attachment.","evidence":["Mukti"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"mukti"},{"id":"aqa-rs-a-sikhism-paper1-1-4-1","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Which one of the following is described as a 'positive' aspect of mukti?\nA Escaping the cycle of rebirth\nB Being freed from the effects of karma\nC Union with God and living in God's presence\nD No longer being reborn as an animal","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C – Union with God and living in God's presence. The 'negative' aspect of mukti is what a person is freed from (rebirth, karma, haumai); the 'positive' aspect is what they gain – merging with God like a drop of water returning to the ocean, and enjoying God's presence and bliss.","evidence":["Positive and negative aspects of mukti"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"mukti aspects"},{"id":"aqa-rs-a-sikhism-paper1-1-4-2","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Give one meaning of the term 'karma' in Sikhism.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"The law of cause and effect: a person's actions (good or bad) have consequences in this life and determine the form of their next birth.","evidence":["'Aape beej aape hi khaahu' – Japji pauri 20, Ang 4"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"karma"},{"id":"aqa-rs-a-sikhism-paper1-1-4-3","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Give one thing that Sikhs believe is needed to achieve mukti.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: God's grace (nadar/Gurprasad); meditation on God's Name (nam japna); overcoming haumai; following the Guru's teaching/becoming gurmukh; doing sewa; living virtuously.","evidence":["Japji pauri 4, Ang 2"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"mukti"},{"id":"aqa-rs-a-sikhism-paper1-1-4-4","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Explain two ways in which belief in karma influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs try to act well, knowing their actions have consequences. Since 'you shall harvest what you plant' (Ang 4), a Sikh will try to be honest, generous and kind, for example by giving dasvandh (a tenth of income) to help others.\n\nSecond way: Sikhs accept responsibility for their own lives rather than blaming others. Belief in karma encourages them to reflect on their behaviour and to change, because good actions and God's grace can improve their spiritual state and lead them towards a better rebirth or mukti.","evidence":["'Aape beej aape hi khaahu' – Ang 4","Dasvandh"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"karma influence"},{"id":"aqa-rs-a-sikhism-paper1-1-4-5","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Explain two ways in which the belief in mukti influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: It gives Sikhs a goal for their lives. Because the aim is union with God, Sikhs prioritise daily prayer and nam japna, such as reciting Nitnem and meditating on 'Waheguru', rather than chasing wealth or fame.\n\nSecond way: Belief in jivan mukti (liberation while still alive) encourages Sikhs to live as gurmukh now, not just to hope for a reward after death. They try to serve others and overcome ego in daily life, for example through sewa in the langar, because a liberated person lives selflessly in the world.","evidence":["Jivan mukti","Nam japna","Sewa"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"mukti influence"},{"id":"aqa-rs-a-sikhism-paper1-1-4-6","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Explain two Sikh teachings about karma and rebirth.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Karma is the law that actions have consequences. Good actions lead to good results and selfish actions to suffering, both in this life and in future lives. A soul's karma decides which life form it is born into next.\n\nSecond teaching: Karma can be overcome by God's grace. Sikhs believe that karma does not lock a person in forever: through God's grace (nadar), meditation on the Name and following the Guru, a person's karma can be cleansed and the cycle of rebirth (samsara/transmigration) can end.\n\nSource: Japji Sahib pauri 4 (Ang 2) says 'By the karma of past actions, the robe of this physical body is obtained; by God's grace, the gate of liberation is found'. This applies both teachings: karma decides the body we are born into, but grace opens the way to mukti.","evidence":["'Karmee aavai kaprra nadree mokh duaar' – Japji pauri 4, Ang 2","'Aape beej aape hi khaahu' – Ang 4","Nadar (grace)"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"karma and rebirth"},{"id":"aqa-rs-a-sikhism-paper1-1-4-7","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"Explain two aspects of mukti in Sikh teaching.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First aspect (negative – what one is freed from): Mukti is liberation from the cycle of birth, death and rebirth, and from the bondage of karma, haumai and the five thieves. The soul no longer has to wander through many life forms.\n\nSecond aspect (positive – what one gains): Mukti is union with God, like a drop of water merging back into the ocean. The liberated soul experiences God's eternal presence and bliss (anand), and some Sikhs speak of reaching Sach Khand, the realm of truth. This can begin in this life – jivan mukti.\n\nSource: The Guru Granth Sahib teaches that the light of the liberated soul merges into God's light, as water mingles with water. Japji pauri 37 (Ang 8) describes Sach Khand as the realm where 'the Formless Lord abides', showing mukti is a positive state of being with God, not just an escape.","evidence":["Jivan mukti","Japji pauri 37, Ang 8 – 'Sach khand vasai nirankar'","Drop and ocean image"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"mukti aspects"},{"id":"aqa-rs-a-sikhism-paper1-1-4-8","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"“Mukti depends on God's grace, not on a person's actions.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nSikh scripture strongly emphasises grace. Japji Sahib says 'By the karma of actions the body is obtained; by grace (nadar) the gate of liberation is found' (Ang 2). The Mool Mantra ends with Gurprasad – God is known by the Guru's grace. This suggests that no amount of good deeds can earn mukti; it is God's free gift.\n\nSikhs believe that relying on one's own actions can increase haumai, the very ego that blocks mukti. If people think they have earned liberation by their good works, they become proud. Recognising dependence on grace keeps a Sikh humble.\n\nGuru Nanak criticised people who thought rituals, pilgrimages or fasting would earn salvation. Only God's grace, not outward actions, transforms the heart.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nSikhs also believe strongly in karma: 'You shall harvest what you plant' (Ang 4). A person's actions shape their life and rebirths, so actions clearly matter. The Guru Granth Sahib teaches that one who does sewa in this world receives a place of honour in God's court (Ang 26).\n\nThe three pillars – nam japna, kirat karna and vand chhakna – are all actions. A manmukh who ignores God and lives selfishly is not liberated, whereas a gurmukh who meditates and serves is. So many Sikhs argue that grace and actions work together: God's grace is given to those who turn to God, and grace in turn enables good actions.\n\nThe five khands also suggest progress through effort: duty (Dharam Khand), knowledge (Gian Khand) and effort (Saram Khand) come before grace (Karam Khand) and truth (Sach Khand). Effort leads to the stage where grace is received. A non-religious person might reject both ideas but argue that what matters morally is people's actions.\n\nCONCLUSION\n\nSikhism clearly teaches that mukti is ultimately a gift of grace – the 'gate of liberation' is opened by God's nadar. But it equally insists on effort: meditation, honest work, sharing and sewa prepare the person to receive grace. The best judgement is that the statement is half right: mukti depends on grace, but grace is not separate from a God-centred life of action.","evidence":["'Nadree mokh duaar' – Japji pauri 4, Ang 2","Gurprasad – Ang 1","'Aape beej aape hi khaahu' – Ang 4","Ang 26 – sewa","Five khands – Japji pauris 34–37"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"grace vs actions"},{"id":"aqa-rs-a-sikhism-paper1-1-4-9","paper":"Beliefs","module":"1.4","moduleTitle":"Karma, rebirth and the aim of mukti","question":"“Belief in rebirth makes people care less about this life.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nSome critics argue that if people believe they will be reborn, they may not take this life so seriously, thinking they will have another chance. They might also accept suffering or injustice as the result of past karma instead of trying to change things.\n\nHumanists and atheists argue that because this is the only life we have, people should make the most of it and work to improve the world now. On this view belief in rebirth risks distracting people from present responsibilities.\n\nThere have been times in history when belief in karma has been used to justify inequality, for example by saying someone was born into a 'low' caste because of past karma – an attitude the Gurus rejected but which still affects some communities.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nSikhs believe the human birth is rare and precious: 'This human body has been given to you. This is your chance to meet the Lord of the Universe' (Ang 12). Belief in rebirth makes this life more important, not less, because wasting it may mean many more lives in other forms before the soul has another chance.\n\nBelief in karma also encourages responsibility: 'You shall harvest what you plant' (Ang 4). Sikhs therefore try to act justly now. The emphasis on jivan mukti – liberation while alive – means Sikhs aim to become God-centred in this life, not postpone it.\n\nSikh practice is very this-worldly. Kirat karna (honest work), vand chhakna (sharing) and sewa all focus on the present. Sikhs are householders, not monks, and the Gurus fought injustice in this world – Guru Tegh Bahadur was martyred defending religious freedom. Sikh charities such as Khalsa Aid show active concern for people suffering now.\n\nCONCLUSION\n\nBelief in rebirth could, in theory, make people complacent, but in Sikhism it does the opposite: the human life is the special opportunity for union with God, and karma means every action counts. Sikh teaching and practice focus strongly on the present life. So, at least for Sikhs, the statement is not convincing; belief in rebirth increases the value of this life.","evidence":["Ang 12 – human birth","Ang 4 – karma","Jivan mukti","Guru Tegh Bahadur's martyrdom (1675)","Khalsa Aid","Humanist view"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"rebirth evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-5-0","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Which one of the following is the final stage of liberation (the fifth khand)?\nA Dharam Khand\nB Gian Khand\nC Karam Khand\nD Sach Khand","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"D – Sach Khand, the realm of truth, where the soul is united with God, 'where the Formless Lord abides' (Japji pauri 37, Ang 8). The order is Dharam, Gian, Saram, Karam, Sach.","evidence":["Japji pauris 34–37, Ang 7–8"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"five khands"},{"id":"aqa-rs-a-sikhism-paper1-1-5-1","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Which one of the following is NOT one of the five thieves (barriers to mukti)?\nA Kaam (lust)\nB Krodh (anger)\nC Daya (compassion)\nD Lobh (greed)","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C – Daya (compassion). Daya is a virtue. The five thieves are kaam (lust), krodh (anger), lobh (greed), moh (worldly attachment) and ahankar (pride).","evidence":["Five thieves"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"barriers"},{"id":"aqa-rs-a-sikhism-paper1-1-5-2","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Give one barrier to mukti in Sikh teaching.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: maya (illusion); haumai (self-centredness); kaam (lust); krodh (anger); lobh (greed); moh (worldly attachment); ahankar (pride).","evidence":["AQA spec list of barriers"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"barriers"},{"id":"aqa-rs-a-sikhism-paper1-1-5-3","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Give the meaning of Gian Khand.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"The realm/stage of knowledge – where a person gains spiritual knowledge and understanding of the vastness of God's creation.","evidence":["Japji pauris 35–36, Ang 7"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"gian khand"},{"id":"aqa-rs-a-sikhism-paper1-1-5-4","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Explain two ways in which belief in the barriers to mukti influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs try to control anger (krodh) and lust (kaam). For example, an amritdhari Sikh promises to avoid adultery, and Sikhs try to respond to insults with patience, because these 'thieves' steal a person's spiritual progress.\n\nSecond way: Sikhs try to avoid greed (lobh) and attachment (moh) by sharing their wealth. Giving dasvandh (a tenth of income) and offering food in the langar trains them not to cling to money or possessions, which helps them break free from maya.","evidence":["Five thieves","Dasvandh","Rehat (Amrit vows)"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"barriers influence"},{"id":"aqa-rs-a-sikhism-paper1-1-5-5","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Explain two ways in which belief in the five khands influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: The first stage, Dharam Khand, reminds Sikhs that they live on earth as a place of duty and that their actions will be judged. This encourages them to live responsibly, working honestly and caring for family and community.\n\nSecond way: The khands show that the spiritual life is a journey that takes effort and grace. This encourages Sikhs to keep growing – learning more about gurbani (Gian Khand), making effort in meditation and sewa (Saram Khand) – rather than feeling they have 'arrived' just by being born Sikh or attending the gurdwara.","evidence":["Japji pauris 34–37","Dharam Khand – earth as a place for dharam"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"five khands influence"},{"id":"aqa-rs-a-sikhism-paper1-1-5-6","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Explain two of the five stages of liberation (khands).\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First stage: Dharam Khand – the realm of duty or righteousness. God created the earth as a place to practise dharam; here people realise their actions are judged and accept responsibility to live a moral life.\n\nSecond stage: Karam Khand – the realm of grace. After effort (Saram Khand), the person receives God's grace and is filled with spiritual power; here live the great devotees who have conquered haumai and are fully devoted to God. This leads to Sach Khand, union with God.\n\nSource: Guru Nanak describes the khands in Japji Sahib, pauris 34–37 (Ang 7–8). Pauri 34 describes God establishing the earth 'as a home for dharam', and pauri 37 says that in the realm of grace 'the Word is power', showing that the final stages depend on God's grace rather than human effort alone.","evidence":["Japji pauri 34, Ang 7 – 'Dharam saal'","Japji pauri 37, Ang 8 – 'Karam khand kee baanee jor'","Sach Khand"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"five khands"},{"id":"aqa-rs-a-sikhism-paper1-1-5-7","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"Explain two Sikh teachings about the barriers to mukti.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Maya (illusion) traps people. Maya makes the temporary world of money, status and pleasure seem more real and important than God, so people forget God's Name. Maya is not evil in itself, but attachment to it keeps people in the cycle of rebirth.\n\nSecond teaching: The five thieves – lust, anger, greed, attachment and pride – rob a person of spiritual wealth. They grow out of haumai (self-centredness) and make a person manmukh. They are overcome by the opposite virtues and by meditation on God's Name.\n\nSource: Gurbani speaks of the five thieves plundering the 'house' of the body while the person sleeps in ignorance, and of the Name of God as the protection against them. Applying this, Sikhs use nam japna and the support of the sangat to guard against these thieves.","evidence":["Maya","Five thieves: kaam, krodh, lobh, moh, ahankar","Haumai","Nam japna"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"barriers"},{"id":"aqa-rs-a-sikhism-paper1-1-5-8","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"“Anger is the most dangerous of the five thieves.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nAnger (krodh) causes immediate harm to others. In a moment of anger people say cruel things, damage relationships and even commit violence. Because Sikhs believe God's light is in every person, harming someone in anger is an offence against God as well as against them.\n\nAnger destroys the calm mind needed for nam japna. A person filled with anger cannot meditate or be content, so it blocks spiritual progress quickly. Anger also undermines the virtue of patience and the ideal of God as Nirvair (without hatred), which Sikhs aim to reflect.\n\nAnger can also be used to justify injustice. Sikhs are called to defend the oppressed, but if this is done out of anger rather than justice, it becomes revenge, not dharam.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Sikhs would say that ahankar (pride) or haumai is more dangerous, because it is the root of all the other thieves. The Guru Granth Sahib calls haumai a 'chronic disease' (Ang 466). Anger usually comes from pride – feeling one's ego has been insulted – so dealing with pride deals with anger too.\n\nOthers might say moh (attachment) or lobh (greed) is more dangerous because it is less obvious. Anger is easy to recognise and regret, but attachment to wealth, status or family can quietly fill a whole life without the person noticing that they have forgotten God. Greed also drives injustice on a large scale, such as exploitation of workers or the environment.\n\nIt can be argued that the five thieves are equally dangerous because they work together, and that the real danger is maya, the illusion that the world matters more than God. A non-religious thinker might add that anger is sometimes healthy, motivating people to fight injustice.\n\nCONCLUSION\n\nAnger is very dangerous because of the visible harm it does. However, Sikh teaching sees haumai and pride as the deeper root from which anger and the other thieves grow. So the stronger conclusion is that pride/ego is the most dangerous, and anger is one of its most destructive expressions.","evidence":["Five thieves","'Haumai deeragh rog hai, daaroo bhee is maahi' – Ang 466","Nirvair – Ang 1","Maya"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"anger"},{"id":"aqa-rs-a-sikhism-paper1-1-5-9","paper":"Beliefs","module":"1.5","moduleTitle":"The five stages of liberation (five khands) and the barriers to mukti","question":"“It is impossible to reach Sach Khand in this life.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nSach Khand is the final realm of truth where the soul is united with the Formless God (Japji pauri 37, Ang 8). Guru Nanak says describing it is 'as hard as steel', suggesting it is far beyond ordinary experience. Most people struggle every day with the five thieves and haumai, so complete union with God may seem impossible while still living in a body.\n\nMany Sikhs think of mukti as ending the cycle of rebirth, which happens at death. On this view a person may make progress through Dharam, Gian and Saram Khand during life, but Sach Khand is only fully reached when the soul leaves the body and merges with God.\n\nSince mukti depends on God's grace (Ang 2), no person can guarantee reaching Sach Khand by their own effort in this life.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nSikhism teaches jivan mukti – liberation while alive. The Guru Granth Sahib describes the jivan mukt as one who lives in the world but is free from ego and constantly absorbed in God's Name. If this is possible, then reaching Sach Khand, at least as a spiritual state, is possible in this life.\n\nSikhs believe the ten Gurus were fully united with God while alive, and the Guru Granth Sahib includes the writings of bhagats such as Kabir and Ravidas, who are seen as having realised God. These examples show it can be done.\n\nMany Sikhs interpret the khands not as places but as stages of spiritual development. Sach Khand is then a state of mind – complete God-centredness (gurmukh) – that can be reached through nam japna, sewa and grace. Humanists, by contrast, would say there is no Sach Khand at all, so the question does not arise.\n\nCONCLUSION\n\nReaching Sach Khand is clearly extremely difficult and depends on God's grace, so it is not something most people achieve. But Sikh teaching on jivan mukti and the example of the Gurus show it is not impossible. The better view is that Sach Khand can be reached in this life by a few, through grace and devotion, and that all Sikhs are called to move towards it now.","evidence":["Japji pauri 37, Ang 8","Jivan mukti","Japji pauri 4, Ang 2 – grace","Bhagats in the GGS"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"sach khand"},{"id":"aqa-rs-a-sikhism-paper1-1-6-0","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Which one of the following terms describes a person who is God-centred?\nA Manmukh\nB Gurmukh\nC Haumai\nD Sahajdhari","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – Gurmukh. Gurmukh means 'facing the Guru' – a person whose life is centred on God and the Guru's teaching. Manmukh is the opposite (self-centred), haumai is ego, and sahajdhari is a Sikh who has not taken amrit.","evidence":["Gurmukh / manmukh"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"gurmukh"},{"id":"aqa-rs-a-sikhism-paper1-1-6-1","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"What does the Sikh term 'haumai' mean?\nA Grace\nB Ego or self-centred pride\nC Honest work\nD The community of Sikhs","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – Ego or self-centred pride. Haumai literally means 'I, I' or 'I-am-ness' – seeing oneself as separate from God and at the centre of everything. Grace is nadar, honest work is kirat karna and the community is the sangat/Panth.","evidence":["'Haumai deeragh rog hai' – Ang 466"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"haumai"},{"id":"aqa-rs-a-sikhism-paper1-1-6-2","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Give one characteristic of a manmukh.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: self-centred; driven by ego (haumai); controlled by the five thieves (lust, anger, greed, attachment, pride); forgets God's Name; attached to maya/worldly things; follows their own mind rather than the Guru.","evidence":["Manmukh"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"manmukh"},{"id":"aqa-rs-a-sikhism-paper1-1-6-3","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Give one way Sikhs believe haumai can be overcome.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: nam japna (meditation on God's Name); sewa (selfless service); following the Guru's teaching/gurbani; joining the sangat; God's grace; developing humility.","evidence":["Ang 466"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"haumai"},{"id":"aqa-rs-a-sikhism-paper1-1-6-4","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Explain two ways in which the aim of becoming gurmukh influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs try to follow the Guru Granth Sahib rather than their own desires. Many take a hukamnama (a random reading from the Guru Granth Sahib) each day and try to apply its teaching, so their decisions are guided by the Guru not by ego.\n\nSecond way: Sikhs do sewa to put others first. For example, a Sikh might volunteer to cook langar or help at a food bank, because a gurmukh serves others selflessly rather than seeking praise or reward.","evidence":["Hukamnama","Sewa"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"gurmukh influence"},{"id":"aqa-rs-a-sikhism-paper1-1-6-5","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Explain two ways in which belief about haumai influences the way Sikhs behave.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs practise humility in worship. They cover their heads, remove shoes, bow before the Guru Granth Sahib and sit on the floor, showing that they are not more important than anyone else and helping to reduce ego.\n\nSecond way: Sikhs try to avoid boasting about good deeds. Because doing sewa or giving money in order to be praised would feed haumai, many Sikhs give dasvandh or serve in the langar quietly, seeing it as God's work rather than their own achievement.","evidence":["Haumai","Gurdwara etiquette","Dasvandh"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"haumai influence"},{"id":"aqa-rs-a-sikhism-paper1-1-6-6","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Explain two Sikh teachings about the difference between gurmukh and manmukh.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: A gurmukh is God-centred – they face the Guru, remember God's Name and accept God's will (hukam). Because they live by the Guru's teaching, they develop virtues such as humility, contentment and compassion, and move towards mukti.\n\nSecond teaching: A manmukh is self-centred – they follow their own mind, are ruled by haumai and the five thieves and are attached to maya. As a result they remain trapped in the cycle of rebirth and feel restless and unhappy, even if they are wealthy.\n\nSource: Guru Nanak's Siddh Gosht and many other hymns in the Guru Granth Sahib contrast the two. For example, gurbani teaches that the gurmukh is absorbed in the Name and so is at peace, while the manmukh wanders in doubt. Applying this, Sikhs see every choice as a step either towards God (gurmukh) or away (manmukh).","evidence":["Siddh Gosht, GGS Ang 938–946","Gurmukh / manmukh","Hukam"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"gurmukh vs manmukh"},{"id":"aqa-rs-a-sikhism-paper1-1-6-7","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"Explain two Sikh teachings about haumai.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Haumai is the main barrier between a person and God. It makes people see themselves as separate from God and from others, and it is the root of the five thieves – lust, anger, greed, attachment and pride. As long as haumai rules, the soul stays in the cycle of rebirth.\n\nSecond teaching: Haumai can be cured. It is overcome by meditating on God's Name, listening to the Guru, doing sewa and through God's grace. When haumai is removed, a person becomes gurmukh and recognises God's light in everyone.\n\nSource: In Asa di Var, Guru Angad writes 'Haumai is a chronic disease, but it also contains its own cure' (Ang 466). This shows both teachings: haumai is a serious illness, but by turning the self towards God through grace, the same self can be healed.","evidence":["'Haumai deeragh rog hai, daaroo bhee is maahi' – Ang 466","Five thieves","Nam japna"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"haumai"},{"id":"aqa-rs-a-sikhism-paper1-1-6-8","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"“It is impossible to completely overcome haumai.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nHaumai is described as a 'chronic disease' (Ang 466) – a long-lasting illness built deep into human nature. Every person has a sense of self and self-interest, so getting rid of it completely may seem unrealistic.\n\nEven good actions can feed haumai. A person who does sewa might become proud of being humble, or proud of their religious knowledge. This shows how subtle ego is, and why many people struggle with it all their lives.\n\nThe five thieves that grow from haumai are constantly encouraged by modern society – advertising feeds greed and attachment, social media encourages pride and comparison. From a non-religious point of view, a healthy ego is necessary for self-respect and survival, so eliminating it entirely would not even be desirable.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nThe same verse says haumai 'also contains its own cure' (Ang 466). Sikh teaching insists that through nam japna and the Guru's grace, haumai can be overcome. If it could not, mukti would be impossible, and the whole Sikh path would be pointless.\n\nSikhs believe the Gurus were completely free from haumai, and the Guru Granth Sahib describes the gurmukh and the jivan mukt as people who live without ego while still in the world. So it has been achieved, and it is the goal for every Sikh.\n\nSikhism also gives practical tools: sewa, sangat, humility in the gurdwara, the Amrit Sanskar where the initiate surrenders their old identity, and daily prayer. These are designed to reduce ego step by step. The five khands show this as a journey ending in grace (Karam Khand) and union (Sach Khand).\n\nCONCLUSION\n\nCompletely overcoming haumai is extremely difficult, and most Sikhs would admit they are still struggling. However, Sikh teaching clearly says it is possible through God's grace, as the example of the Gurus shows. So the statement is too strong: haumai cannot be overcome by human effort alone, but with grace it can be completely overcome.","evidence":["'Haumai deeragh rog hai, daaroo bhee is maahi' – Ang 466","Jivan mukti","Five khands","Sewa and sangat"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"haumai evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-6-9","paper":"Beliefs","module":"1.6","moduleTitle":"Being gurmukh rather than manmukh, and the elimination of haumai","question":"“You can be a good person without being gurmukh.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nMany people who do not believe in God are kind, honest and generous. Humanists argue that morality is based on reason, empathy and the effects of actions on others, not on religious belief. A non-religious volunteer at a homeless shelter is clearly a good person.\n\nSikhism itself teaches that God's light is in everyone (Ang 13), so it is consistent to say that good people exist in all religions and none. The Guru Granth Sahib includes writings of Hindu and Muslim saints, showing that goodness is not limited to Sikhs.\n\nGuru Nanak praised the honest carpenter Bhai Lalo over the corrupt rich man Malik Bhago because of how they lived, not what label they carried. So goodness is shown in actions.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nFor Sikhs, being gurmukh means being God-centred, and they would say true goodness comes from this. A person who does good deeds while forgetting God may still be acting from haumai – wanting praise or feeling superior. Only when ego is overcome by remembering God is goodness fully pure.\n\nSikhs believe virtues are ultimately gifts of God's grace. 'Truth is higher than everything, but higher still is truthful living' (Ang 62) refers to living in line with God's truth. Without this, a person may be outwardly good but remain manmukh, trapped in the cycle of rebirth.\n\nAlso, being gurmukh is not about being Sikh by name; it is about facing God. A non-Sikh who lives selflessly and humbly may already be close to gurmukh in Sikh eyes, which shows the two ideas are closely linked.\n\nCONCLUSION\n\nIn everyday terms, people can certainly be good without being gurmukh, and Sikh teaching recognises goodness in all. But from a Sikh perspective, goodness reaches its full meaning only when it flows from a God-centred life free from ego. So the statement is true at a human level, but Sikhs would say being gurmukh is what makes goodness complete and leads to mukti.","evidence":["Ang 13","Bhai Lalo and Malik Bhago","Ang 62","Bhagats in the GGS","Humanist ethics"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"good without gurmukh"},{"id":"aqa-rs-a-sikhism-paper1-1-7-0","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Which one of the following quotations from the Guru Granth Sahib is used to support the equality of women?\nA 'This human body has been given to you'\nB 'So why call her inferior? From her, kings are born'\nC 'You shall harvest what you plant'\nD 'In the realm of truth the Formless Lord abides'","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – 'So why call her inferior? From her, kings are born' (Guru Nanak, Asa di Var, Ang 473). Guru Nanak argued that women give birth to all people, including kings, so it is wrong to regard them as lesser. The other quotations are about human life, karma and Sach Khand.","evidence":["'So kio manda aakhiai jit jameh rajaan' – Ang 473"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"women"},{"id":"aqa-rs-a-sikhism-paper1-1-7-1","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Which one of the following best expresses the Sikh belief in the oneness of humanity?\nA All humans are the same caste\nB All humans come from the One God and share the same divine light\nC Only Sikhs carry God's light\nD People are equal only after initiation","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – All humans come from the One God and share the same divine light. Bhagat Kabir writes 'From the One Light, the entire universe welled up; so who is good and who is bad?' (Ang 1349–50). The other options either limit God's light or confuse equality with caste or initiation.","evidence":["'Aval Allah noor upaaiaa' – Ang 1349–50"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"oneness"},{"id":"aqa-rs-a-sikhism-paper1-1-7-2","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Give one reason why Sikhs believe all people are equal.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: all people were created by the One God (Ik Onkar); God's light (jot) is in every person; God is the father of all ('We are the children of the One' – Ang 611); in God's court there is no caste (Ang 349); the Gurus taught and showed equality.","evidence":["Ang 611","Ang 349"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"equality"},{"id":"aqa-rs-a-sikhism-paper1-1-7-3","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Give one example of how Sikh teaching rejected discrimination against women.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: Guru Amar Das condemned sati (widow-burning); he discouraged purdah/veiling; women may lead worship and read the Guru Granth Sahib; Guru Nanak's teaching 'why call her inferior?' (Ang 473); women can be initiated into the Khalsa and are given the name Kaur; widows may remarry.","evidence":["Ang 473","Guru Amar Das"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"women"},{"id":"aqa-rs-a-sikhism-paper1-1-7-4","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Explain two ways in which belief in the oneness of humanity influences Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs welcome everyone into the gurdwara and the langar, whatever their religion, race or social background. Everyone sits on the floor together to eat the same food, which shows that no one is higher or lower than anyone else.\n\nSecond way: Sikhs help people in need regardless of who they are. For example, Sikh charities such as Khalsa Aid provide food and shelter to refugees and disaster victims of every faith, because they see God's light in all humans.","evidence":["Ang 1349–50","Langar","Khalsa Aid"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"oneness influence"},{"id":"aqa-rs-a-sikhism-paper1-1-7-5","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Explain two different ways in which Sikhs show the equality of men and women.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: In worship, women and men have the same religious roles. A woman may be a granthi, read from the Guru Granth Sahib, perform kirtan or lead Ardas, because Sikh teaching gives women complete spiritual equality.\n\nSecond way: In identity and initiation, women are treated equally. Women can take amrit and wear the five Ks, and are given the name Kaur, which means they do not have to take a husband's or father's family name and have their own dignity as members of the Khalsa.","evidence":["Ang 473","Sikh Rehat Maryada","Kaur"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"gender equality"},{"id":"aqa-rs-a-sikhism-paper1-1-7-6","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Explain two Sikh teachings about the equality of all people.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: All people come from the One God and contain God's light (jot). Since God is the parent of all, everyone is part of one human family and deserves equal respect, whatever their religion, race or nationality.\n\nSecond teaching: Caste and social status have no value in God's eyes. Sikhs reject the caste system, since what matters is a person's devotion and actions, not the family they were born into.\n\nSource: Guru Nanak teaches: 'Recognise the Lord's Light within all, and do not ask about caste; there is no caste in the world hereafter' (Ang 349). Guru Arjan also writes 'The One God is our father; we are the children of the One' (Ang 611). These apply directly: if all are children of one father, caste divisions are false.","evidence":["'Jaanahu jot na poochhahu jaatee' – Ang 349","'Ek pita ekas ke ham baarik' – Ang 611","Rejection of caste"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"equality"},{"id":"aqa-rs-a-sikhism-paper1-1-7-7","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"Explain two Sikh teachings about the status of women.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Women are completely equal to men spiritually. Women contain the same divine light, can achieve mukti, and can take part fully in worship and leadership. No ritual is closed to women in Sikh teaching.\n\nSecond teaching: Women should be respected and not treated as impure or inferior. Guru Nanak rejected ideas that women are polluting (for example during menstruation or after childbirth), and Guru Amar Das opposed practices such as sati and purdah that harmed women.\n\nSource: Guru Nanak writes in Asa di Var: 'From woman, man is born… So why call her inferior? From her, kings are born' (Ang 473). This applies both teachings: since all humans, even rulers, owe their lives to women, it is wrong to treat women as less valuable.","evidence":["'So kio manda aakhiai jit jameh rajaan' – Ang 473","Guru Amar Das and sati","Sikh Rehat Maryada"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"women"},{"id":"aqa-rs-a-sikhism-paper1-1-7-8","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"“Women and men are completely equal in Sikhism today.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nIn Sikh teaching, women and men are spiritually identical: both contain God's light, can achieve mukti and can do every religious role. Guru Nanak asked 'why call her inferior? From her, kings are born' (Ang 473). The Sikh Rehat Maryada allows women to be granthis, to perform kirtan, read the Guru Granth Sahib and lead Ardas.\n\nWomen are initiated into the Khalsa in the same way as men and are given the name Kaur, which gives them an independent identity. History provides strong role models: Mata Khivi ran the langar with Guru Angad and is praised in the Guru Granth Sahib (Ang 967); Mai Bhago led soldiers into battle in 1705; Mata Sahib Kaur is seen as the 'mother of the Khalsa'.\n\nIn modern times women hold senior positions: Bibi Jagir Kaur became the first woman president of the SGPC (the committee that manages historic gurdwaras in Punjab) in 1999, and many UK gurdwara committees include women.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nIn practice, equality is not complete. Women are rarely chosen as Panj Pyare at Amrit ceremonies, and there have been disputes about whether women may perform kirtan inside the Harimandir Sahib, which has traditionally been done by men. Most granthis and gurdwara committee leaders are still men.\n\nCultural attitudes from Punjabi society, rather than Sikh teaching, still affect some families – such as preference for sons, pressure over dowry, and expectations that women do most of the cooking in langar. Campaigners within the Sikh community have challenged these practices.\n\nSome argue that roles can be equal without being identical, and that women in some families choose different roles freely. Others see this as an excuse for inequality.\n\nCONCLUSION\n\nSikh teaching clearly supports complete equality of women and men, and that equality is visible in worship, initiation and naming. However, in some areas of practice and culture, especially leadership and Panj Pyare, equality has not been fully achieved. The fairest judgement is that Sikhism teaches complete equality, but Sikhs today are still working to make practice match the Gurus' teaching.","evidence":["Ang 473","Mata Khivi – Ang 967","Mai Bhago","Bibi Jagir Kaur (SGPC president 1999)","Debate over women in Panj Pyare and kirtan at Harimandir Sahib"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"women equality"},{"id":"aqa-rs-a-sikhism-paper1-1-7-9","paper":"Beliefs","module":"1.7","moduleTitle":"The oneness of humanity and the equality of all, including the equality of women with men","question":"“Belief in the oneness of humanity is the most important teaching in Sikhism.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nThe oneness of humanity follows directly from Ik Onkar: if there is one God who created all and whose light is in all, then all people are one family. Kabir's verse 'From the One Light, the entire universe welled up; so who is good and who is bad?' (Ang 1349–50) is central to Sikh identity.\n\nIt shapes almost every Sikh practice. Langar, where everyone eats together on the floor; the four doors of the Harimandir Sahib open to all directions; the inclusion of Hindu and Muslim saints in the Guru Granth Sahib; the abolition of caste in the Khalsa – all express this belief. Without it, Sikhism would lose its most distinctive social message.\n\nIt is also very relevant today, in a world of racism, religious conflict and inequality. Sikh service to people of all backgrounds, such as Khalsa Aid's work with refugees, puts this belief into practice.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Sikhs would say belief in God (Ik Onkar) is more important, because the oneness of humanity is a consequence of it. Without one God there would be no single source of human unity. The Mool Mantra, not a teaching about humanity, opens the Guru Granth Sahib.\n\nOthers would argue the aim of life – mukti through overcoming haumai and becoming gurmukh – is the most important teaching, since Sikhs believe human life is an opportunity to unite with God (Ang 12). Belief in equality is a way of living that helps reach that goal.\n\nSome also point out that a belief is only as important as its practice. Caste-based gurdwaras and discrimination still exist in some places, which suggests that in practice other teachings may receive more attention. A humanist might agree that human oneness is the most valuable teaching but say it does not depend on God.\n\nCONCLUSION\n\nThe oneness of humanity is clearly one of the most important and distinctive teachings, shaping worship, service and identity. But in Sikh thought it flows from belief in Ik Onkar and serves the aim of union with God. So it is best seen as the most important social teaching of Sikhism, while belief in the One God remains the foundation.","evidence":["Ang 1349–50","Ik Onkar – Ang 1","Ang 12","Langar; four doors of Harimandir Sahib","Khalsa Aid"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"oneness evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-8-0","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"In the story of Bhai Lalo and Malik Bhago, why did Guru Nanak choose to eat with Bhai Lalo?\nA Bhai Lalo was from a high caste\nB Bhai Lalo earned his living honestly\nC Malik Bhago refused to invite him\nD Bhai Lalo was a Sikh Guru","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – Bhai Lalo earned his living honestly. Bhai Lalo was a poor carpenter of a so-called 'low' caste; Malik Bhago was a rich official who exploited the poor. In the story, Lalo's simple bread produced milk and Bhago's rich food produced blood, showing that honest work and character matter, not wealth or caste.","evidence":["Janamsakhi story of Bhai Lalo and Malik Bhago"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"bhai lalo"},{"id":"aqa-rs-a-sikhism-paper1-1-8-1","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Which one of the following shows equality in the Guru Granth Sahib?\nA It is written only by the Sikh Gurus\nB It contains hymns by Hindu and Muslim saints of different castes\nC It may only be read by men\nD It is written only in Sanskrit","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – It contains hymns by Hindu and Muslim saints of different castes, such as Kabir (a weaver), Ravidas (a leather-worker, regarded as 'untouchable' at the time) and the Muslim Sufi Sheikh Farid. Their words are treated with the same respect as the Gurus' words. It is written in Gurmukhi script, and anyone may read it.","evidence":["Bhagat bani in the GGS – Kabir, Ravidas, Sheikh Farid, Namdev"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"ggs equality"},{"id":"aqa-rs-a-sikhism-paper1-1-8-2","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Give one example from the life of Guru Gobind Singh that shows equality.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: the Panj Pyare who came forward in 1699 were from different castes and regions; he created the Khalsa, in which all drank amrit from the same bowl, rejecting caste; he gave all men the name Singh and all women the name Kaur to remove caste surnames; he himself was initiated by the Panj Pyare, showing the Guru and Khalsa are equal.","evidence":["Vaisakhi 1699","Panj Pyare"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"guru gobind singh"},{"id":"aqa-rs-a-sikhism-paper1-1-8-3","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Give one example of a non-Sikh contributor whose writings are in the Guru Granth Sahib.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: Bhagat Kabir; Bhagat Ravidas; Sheikh Farid; Bhagat Namdev; Bhagat Trilochan; Bhagat Dhanna; Bhagat Sain; Bhagat Ramanand; Bhagat Beni; Bhagat Pipa; Bhagat Sadhna; Bhagat Surdas; Bhagat Jaidev; Bhagat Parmanand; Bhagat Bhikhan.","evidence":["Bhagat bani"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"bhagats"},{"id":"aqa-rs-a-sikhism-paper1-1-8-4","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Explain two ways in which the example of Guru Nanak influences Sikh attitudes to equality today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Guru Nanak ate with the poor carpenter Bhai Lalo rather than the rich Malik Bhago. This influences Sikhs to judge people by their honesty and character, not by wealth or caste, and to treat poor people with dignity.\n\nSecond way: Guru Nanak's companion was Bhai Mardana, a Muslim musician, and he taught 'There is no Hindu, there is no Muslim'. This encourages Sikhs today to respect people of other faiths and to take part in interfaith work and serve everyone in the langar.","evidence":["Bhai Lalo and Malik Bhago","Bhai Mardana","Guru Nanak at Bein"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"guru nanak equality"},{"id":"aqa-rs-a-sikhism-paper1-1-8-5","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Explain two ways in which equality is shown in Sikhism today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Through the langar. Everyone – rich or poor, Sikh or non-Sikh – sits on the floor together and is served the same vegetarian food, so no one is given a higher place.\n\nSecond way: Through the names Singh and Kaur. Many Sikhs use these names instead of caste-based family names, which shows that all Sikhs are equal members of one family, and women have their own name rather than being identified only through a husband.","evidence":["Langar","Singh and Kaur"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"equality today"},{"id":"aqa-rs-a-sikhism-paper1-1-8-6","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Explain two ways in which the Guru Granth Sahib expresses the equality of all.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Through its content and authors. The Guru Granth Sahib contains hymns by Hindu and Muslim saints (bhagats) from many castes, including Kabir, a weaver, and Ravidas, a leather-worker regarded as an 'untouchable' at the time. Their words are treated as equally holy as those of the Gurus.\n\nSecond way: Through its teaching. Many hymns directly reject caste and gender discrimination and teach that God's light is in everyone. As the living Guru, it is open for anyone to read and hear in Gurmukhi.\n\nSource: Guru Nanak's words 'Recognise the Lord's Light within all, and do not ask about caste; there is no caste in the world hereafter' (Ang 349), and Bhagat Ravidas's hymns of devotion included in the scripture, show that the Guru Granth Sahib not only teaches equality but practises it in who is included.","evidence":["Ang 349","Bhagat Ravidas and Kabir in the GGS","Gurmukhi"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"ggs equality"},{"id":"aqa-rs-a-sikhism-paper1-1-8-7","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"Explain two ways in which the lives of the Gurus showed the equality of all.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Guru Nanak rejected caste and wealth as signs of worth. He chose to eat with the honest carpenter Bhai Lalo rather than the corrupt rich official Malik Bhago, and started the practice of communal eating. He travelled with Bhai Mardana, a Muslim.\n\nSecond way: Guru Gobind Singh created the Khalsa in 1699. The Panj Pyare who volunteered came from different castes, yet all drank amrit from the same bowl, and all men were named Singh and all women Kaur. Guru Gobind Singh then asked the Panj Pyare to initiate him, showing the Guru and the Khalsa were equal.\n\nSource: Guru Nanak's teaching in the Guru Granth Sahib, 'From woman, man is born… So why call her inferior?' (Ang 473), and Guru Amar Das's rule that all must eat in the langar before meeting him – even the Emperor Akbar – show the Gurus applying equality to gender and status.","evidence":["Bhai Lalo and Malik Bhago","Vaisakhi 1699","Ang 473","Akbar and Guru Amar Das's langar ('pehle pangat, pichhe sangat')"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"gurus equality"},{"id":"aqa-rs-a-sikhism-paper1-1-8-8","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"“Sikhs today have achieved the equality the Gurus taught.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nThe langar is a powerful and continuing sign of equality: every day millions of people are fed in gurdwaras across the world, sitting together regardless of religion, caste or wealth. At the Harimandir Sahib in Amritsar, tens of thousands of people are fed daily by volunteers.\n\nWomen can take every religious role – reading the Guru Granth Sahib, kirtan, Ardas – and are named Kaur. Women have become leaders, such as Bibi Jagir Kaur, the first woman president of the SGPC. Sikhs serve people of all faiths through organisations such as Khalsa Aid and through langar on the streets for homeless people in UK cities.\n\nThe names Singh and Kaur continue to reject caste, and the Amrit ceremony still uses one bowl for all initiates.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nCaste has not disappeared. Some Sikhs still consider caste when arranging marriages, and in the UK some gurdwaras are associated with particular caste groups, such as Ramgarhia gurdwaras. Many members of the Ravidassia community, many of whom felt discriminated against, have formed their own separate places of worship.\n\nGender equality is also incomplete. Most granthis and gurdwara committee members are men, women are rarely chosen as Panj Pyare, and there have been disputes about women performing kirtan at the Harimandir Sahib. Cultural pressures such as son-preference and dowry still affect some families.\n\nSome Sikhs argue that these problems come from Punjabi culture, not Sikhism, and that the Gurus' teaching, especially Ang 349 and Ang 473, gives clear grounds to challenge them. But the fact that these problems exist shows equality has not been fully achieved.\n\nCONCLUSION\n\nSikhs have achieved a great deal: langar, sangat, naming and initiation still powerfully express the Gurus' teaching. But caste divisions and gender inequality persist in parts of the community. The fairest conclusion is that Sikhs today have achieved equality in principle and in many practices, but not yet completely in social life, and many Sikhs see continuing this work as part of following the Gurus.","evidence":["Harimandir Sahib langar","Bibi Jagir Kaur","Ramgarhia and Ravidassia communities in the UK","Ang 349","Ang 473","Khalsa Aid"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"equality today evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-8-9","paper":"Beliefs","module":"1.8","moduleTitle":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","question":"“The Guru Granth Sahib is the best example of Sikh belief in equality.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nThe Guru Granth Sahib is the living Guru, so its example has supreme authority. It contains the writings not only of six Sikh Gurus but also of Hindu and Muslim saints from many castes, such as Kabir, Ravidas, Namdev and Sheikh Farid. Including a leather-worker considered 'untouchable' and a Muslim Sufi alongside the Gurus is a remarkable statement of equality, made by Guru Arjan when he compiled the Adi Granth in 1604.\n\nIts teaching is clear: 'Recognise the Lord's Light within all, and do not ask about caste' (Ang 349) and 'So why call her inferior? From her, kings are born' (Ang 473). Because it is permanent and unchanging, it is a fixed standard against which Sikhs can measure their behaviour.\n\nIt is also accessible: anyone may read it, and it is written in Gurmukhi in the language of ordinary people rather than a priestly language.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany would say the langar is the best example, because it shows equality in action every day. People sit side by side on the floor and eat the same food; Guru Amar Das even required the Emperor Akbar to eat in the langar before meeting him. Actions may speak louder than words.\n\nOthers would point to Vaisakhi 1699, when Guru Gobind Singh created the Khalsa. Men and women of all castes drank amrit from the same bowl and received the names Singh and Kaur, and the Guru himself was initiated by the Panj Pyare – a dramatic sign that leader and followers are equal.\n\nThe lives of the Gurus also give powerful examples, such as Guru Nanak's choice of Bhai Lalo over Malik Bhago. A non-religious person might argue that what matters is how Sikhs live today, for example in serving the homeless, rather than any text.\n\nCONCLUSION\n\nThe Guru Granth Sahib is a very strong example because, as the Guru, it both teaches equality and practises it through its inclusion of diverse voices. However, Sikh equality is expressed most visibly in the langar and the Khalsa. The best judgement is that the Guru Granth Sahib is the foundation of Sikh equality, while the langar and Khalsa are its clearest living examples.","evidence":["Adi Granth compiled by Guru Arjan (1604)","Ang 349","Ang 473","Langar and Akbar","Vaisakhi 1699","Bhai Lalo"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"ggs equality evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-9-0","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Which one of the following is the Punjabi term for material sewa (service using money or possessions)?\nA Tan\nB Man\nC Dhan\nD Nam","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C – Dhan. Dhan sewa is material service, such as giving money (dasvandh) or food. Tan sewa is physical service, man sewa is mental/intellectual service, and nam is God's Name.","evidence":["Tan, man, dhan sewa"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"types of sewa"},{"id":"aqa-rs-a-sikhism-paper1-1-9-1","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Which one of the following is an example of man (mental) sewa?\nA Washing dishes in the langar\nB Teaching Punjabi or gurbani to children at the gurdwara\nC Donating money to a charity\nD Cleaning the shoes of the sangat","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – Teaching Punjabi or gurbani to children. Man sewa uses a person's mind, knowledge or skills for others. Washing dishes and cleaning shoes are tan (physical) sewa; donating money is dhan (material) sewa.","evidence":["Man sewa"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"types of sewa"},{"id":"aqa-rs-a-sikhism-paper1-1-9-2","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Give one example of tan (physical) sewa.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: cooking, serving or cleaning in the langar; washing dishes; cleaning the gurdwara; looking after shoes of the sangat; helping in disaster relief; caring for sick or elderly people.","evidence":["Tan sewa"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"tan sewa"},{"id":"aqa-rs-a-sikhism-paper1-1-9-3","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Give one reason why sewa is important to Sikhs.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: it helps overcome haumai (ego); it is serving God, whose light is in all people; it expresses the equality of all; it was taught and modelled by the Gurus; it leads towards mukti/a place of honour in God's court (Ang 26); it puts the teaching of vand chhakna into practice.","evidence":["Ang 26"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"sewa importance"},{"id":"aqa-rs-a-sikhism-paper1-1-9-4","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Explain two ways in which sewa influences the lives of Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Sikhs give time to serve in the gurdwara, especially in the langar. Families may volunteer to cook and clean on a particular day, which gives everyone, including children, a habit of serving others humbly.\n\nSecond way: Sikhs serve the wider community, not just other Sikhs. For example, during the COVID-19 pandemic many UK gurdwaras delivered free meals to NHS workers, vulnerable people and the homeless, and Khalsa Aid provides relief in disasters around the world.","evidence":["Langar","Khalsa Aid","COVID-19 gurdwara meals"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"sewa influence"},{"id":"aqa-rs-a-sikhism-paper1-1-9-5","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Explain two different types of sewa.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First type: Tan sewa is physical service, using the body. For example, a Sikh might wash dishes in the langar or clean the gurdwara floor, which is humbling work that reduces haumai.\n\nSecond type: Dhan sewa is material service, using money or possessions. Many Sikhs give dasvandh – a tenth of their income – to the gurdwara or to charity, which helps others and stops them becoming greedy or attached to wealth.","evidence":["Tan, man, dhan sewa","Dasvandh"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"types of sewa"},{"id":"aqa-rs-a-sikhism-paper1-1-9-6","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Explain two Sikh teachings about the importance of sewa.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Sewa is a way of serving God. Because God's light is in every person, serving people is serving God. It is a key part of being gurmukh and of the path to mukti, alongside nam japna.\n\nSecond teaching: Sewa must be selfless (nishkam). It should be done without wanting reward or praise, otherwise it feeds haumai. When done humbly, it destroys ego and teaches equality, because the person serving puts themselves at the same level as everyone else.\n\nSource: Guru Nanak teaches 'In the midst of this world, do sewa, and you shall be given a place of honour in the Court of the Lord' (Ang 26). This shows that sewa is not optional but central to the Sikh path, and that its reward comes from God, so it should not be done for human praise.","evidence":["'Vich duniaa sev kamaaeeai taa dargeh baisan paaeeai' – Ang 26","Nishkam sewa","Haumai"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"sewa teachings"},{"id":"aqa-rs-a-sikhism-paper1-1-9-7","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"Explain two examples from Sikh history that show the importance of sewa.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First example: Guru Amar Das served Guru Angad for many years, including fetching water for him every day before dawn, even when he was old. His humble service is one reason he was chosen as the third Guru, showing that sewa is valued above status.\n\nSecond example: Bhai Kanhaiya served water to wounded soldiers on both sides during a battle at Anandpur. When others complained, Guru Gobind Singh praised him, saying he saw the Guru's light in everyone, and gave him ointment to treat their wounds too. This shows sewa must be given to all, even enemies.\n\nSource: Guru Nanak's teaching that the one who does sewa in this world gains a place of honour in God's court (Ang 26) explains why Sikhs remember these examples: they show sewa as the practical form of devotion. Bhai Kanhaiya is often seen as an inspiration for the humanitarian work of Sikh organisations today.","evidence":["Guru Amar Das's sewa to Guru Angad","Bhai Kanhaiya","Ang 26"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"sewa history"},{"id":"aqa-rs-a-sikhism-paper1-1-9-8","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"“Sewa is more important than prayer for Sikhs.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nSewa makes a real difference to other people's lives. Feeding the hungry in the langar, caring for the sick or giving dasvandh to charity meets real needs, whereas prayer might seem to benefit only the person praying. Guru Nanak taught that one who does sewa in this world gains a place of honour in God's court (Ang 26).\n\nSewa directly attacks haumai. Washing dishes or cleaning shoes humbles a person in a way that private prayer may not. The Gurus themselves showed sewa: Guru Amar Das served Guru Angad for years before becoming Guru, and Bhai Kanhaiya served water to soldiers of both sides.\n\nSikhism is a practical religion of householders. Guru Nanak criticised people who prayed or performed rituals while ignoring the poor, teaching that truthful living is higher than truth (Ang 62). A humanist would agree that serving others is the true measure of a good life.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nFor Sikhs, prayer and nam japna are the root of everything. Guru Ram Das describes the true Sikh as one who rises early, bathes and meditates on the Name (Ang 305), and only then goes about the day's work. Without remembering God, sewa can become a show to gain praise, which increases haumai.\n\nSewa is meant to be nishkam – selfless – and Sikhs believe this is possible only with God's grace, gained through prayer and meditation. Prayer gives the strength, humility and love that make sewa genuine.\n\nThe three pillars – nam japna, kirat karna and vand chhakna – are presented together. In the gurdwara, prayer and service are joined: Ardas is said and the food blessed before langar is served. So Sikhs would generally see them as two sides of one devotion rather than competing priorities.\n\nCONCLUSION\n\nSewa is clearly essential and is often the most visible part of Sikh life. However, in Sikh teaching it grows out of remembering God; prayer without service is incomplete, but service without prayer risks becoming ego. The stronger conclusion is that neither is more important: for Sikhs, prayer inspires sewa and sewa expresses prayer.","evidence":["Ang 26","Ang 62","Ang 305","Guru Amar Das; Bhai Kanhaiya","Three pillars","Humanist view"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"sewa vs prayer"},{"id":"aqa-rs-a-sikhism-paper1-1-9-9","paper":"Beliefs","module":"1.9","moduleTitle":"Sewa: the importance and priority of service to others","question":"“Dhan (material) sewa is the least important type of sewa.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nGiving money can be easy for wealthy people and may involve little personal sacrifice or humility. Tan sewa, such as washing dishes or cleaning shoes, is more effective at reducing haumai, because the person physically serves others at the lowest level.\n\nMan sewa, using one's mind and skills – for example teaching gurbani, counselling or giving professional help for free – involves personal commitment and can change lives in ways money cannot.\n\nThere is also a risk that material giving is done for status, such as having one's name read out as a donor, which feeds pride rather than overcoming it. The Gurus' greatest examples of sewa – Guru Amar Das fetching water, Bhai Kanhaiya tending wounded soldiers – were physical, not financial.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nDhan sewa is necessary for everything else. Without donations, gurdwaras could not run langar, buy food or support charities. Khalsa Aid's disaster relief depends on money given by ordinary Sikhs. Material sewa can therefore help far more people than one person's physical work.\n\nSikhs are taught the practice of dasvandh – giving a tenth of income – which is a serious and regular discipline. It directly tackles lobh (greed) and moh (attachment to wealth), two of the five thieves, so it is spiritually important too. Vand chhakna, sharing what one has, is one of the three pillars of Sikhism.\n\nSikh teaching does not rank the three types; sewa is valued by the intention behind it. A poor person's small gift given humbly may be worth more than a large showy donation. Many Sikhs would say tan, man and dhan should all be offered together.\n\nCONCLUSION\n\nPhysical sewa may be the most effective at reducing ego, but this does not make material sewa least important. Dhan sewa makes most community service possible and tackles greed and attachment directly. The best judgement is that all three types are equally important when done selflessly, so the statement is not convincing.","evidence":["Tan, man, dhan sewa","Dasvandh","Vand chhakna","Khalsa Aid","Five thieves: lobh and moh"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"dhan sewa"},{"id":"aqa-rs-a-sikhism-paper1-1-10-0","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"What is the sangat?\nA The holy book of Sikhism\nB The Sikh religious community or congregation\nC The canopy over the Guru Granth Sahib\nD The free kitchen","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – The Sikh religious community or congregation. Sangat means 'company' or 'association', especially the gathering of people who worship together in the presence of the Guru Granth Sahib. The canopy is the chanani and the free kitchen is the langar.","evidence":["Sangat"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"sangat"},{"id":"aqa-rs-a-sikhism-paper1-1-10-1","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"According to the Guru Granth Sahib, how is the true sangat (satsangat) recognised?\nA By the size of its building\nB By the wealth of its members\nC As the place where the Name of the One God is spoken\nD As a gathering only of amritdhari Sikhs","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C – As the place where the Name of the One God is spoken. Guru Nanak asks 'How is the Society of the Saints to be known? There, the Name of the One Lord is chanted' (Ang 72). The true sangat is defined by devotion, not wealth, size or status.","evidence":["'Satsangat kaisee jaaneeai, jithai eko naam vakhaaneeai' – Ang 72"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"satsangat"},{"id":"aqa-rs-a-sikhism-paper1-1-10-2","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"Give one way the sangat supports individual Sikhs.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: worshipping together, e.g. kirtan and Ardas; encouragement to keep to the Sikh path/become gurmukh; practical help in times of need, e.g. bereavement or illness; learning about Sikhism and Punjabi; a sense of belonging and identity; opportunities to do sewa.","evidence":["Sangat"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"sangat support"},{"id":"aqa-rs-a-sikhism-paper1-1-10-3","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"Give one meaning of 'Guru Panth'.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"The whole Sikh community (the Khalsa Panth) as Guru – Guru Gobind Singh gave spiritual authority to the community as well as to the scripture, so collective decisions of the sangat have the Guru's authority.","evidence":["Guru Granth, Guru Panth"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"guru panth"},{"id":"aqa-rs-a-sikhism-paper1-1-10-4","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"Explain two ways in which the sangat is important for Sikhs today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: The sangat helps Sikhs worship. Hearing kirtan and the Guru Granth Sahib with others focuses the mind on God, and many Sikhs find it easier to meditate on the Name in the congregation than alone.\n\nSecond way: The sangat gives practical and moral support. For example, when someone dies the sangat gathers to say prayers and supports the family, and young Sikhs learn Punjabi and the Sikh way of life through classes and camps run by the community.","evidence":["Ang 72","Kirtan","Gurdwara classes"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"sangat importance"},{"id":"aqa-rs-a-sikhism-paper1-1-10-5","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"Explain two ways in which belonging to the sangat influences how Sikhs behave.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: It encourages Sikhs to do sewa. In the sangat, people take turns to cook, serve and clean in the langar, which builds habits of humility and service to others.\n\nSecond way: It encourages Sikhs to live as gurmukh. Being with people who are trying to live by the Guru's teaching helps a Sikh avoid the five thieves and bad company, just as gurbani teaches that good company shapes the soul.","evidence":["Sewa","Gurmukh","Ang 72"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"sangat influence"},{"id":"aqa-rs-a-sikhism-paper1-1-10-6","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"Explain two Sikh teachings about the importance of the sangat.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: In the sangat, God's Name is remembered, which helps believers grow spiritually. Joining the satsangat brings the person closer to God and helps them overcome haumai, so it is an important part of the path to mukti.\n\nSecond teaching: The sangat has the authority of the Guru. Guru Gobind Singh taught that the Guru is present where the Khalsa or sangat is gathered in the presence of the Guru Granth Sahib, and gave the community (Guru Panth) authority to make decisions. So the sangat is not just a group of individuals but a sacred body.\n\nSource: Guru Nanak writes 'How is the Society of the Saints to be known? There, the Name of the One Lord is chanted' (Ang 72). This shows that the sangat is defined by meditation on God, and that this is why it is spiritually important.","evidence":["Ang 72","Guru Granth / Guru Panth","Gurmatta"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"sangat teachings"},{"id":"aqa-rs-a-sikhism-paper1-1-10-7","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"Explain two ways in which the sangat expresses Sikh belief in equality.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Everyone sits on the floor together in the diwan hall, at the same level, with no special seats for rich or important people. Men and women of any background may attend and take part.\n\nSecond way: Anyone in the sangat may do sewa or lead worship, such as reading from the Guru Granth Sahib or performing kirtan, because Sikhism has no priestly caste. Everyone eats the same food in the langar and receives the same karah prasad.\n\nSource: Guru Nanak's teaching 'Recognise the Lord's Light within all, and do not ask about caste' (Ang 349) explains why the sangat is open to all. Guru Amar Das's rule that all must sit in the langar before seeing the Guru shows the sangat making equality real.","evidence":["Ang 349","Pangat and sangat","Karah prasad"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"sangat equality"},{"id":"aqa-rs-a-sikhism-paper1-1-10-8","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"“Sikhs need the sangat to live a religious life.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nGuru Nanak teaches that the true company (satsangat) is where the Name of the One God is spoken (Ang 72). Sikhs believe that good company shapes the soul, and that remembering God is easier in the sangat than alone. Kirtan, Ardas and readings from the Guru Granth Sahib are shared experiences.\n\nMany important Sikh practices are communal and need the sangat: langar, sewa, akhand paths, gurpurb celebrations, Amrit Sanskar (performed by the Panj Pyare) and Anand Karaj all happen in the community. The Guru Panth itself – the community with the Guru's authority – makes collective decisions (gurmattas).\n\nThe sangat supports Sikhs practically and morally – teaching children, supporting the bereaved and encouraging people to resist the five thieves. Without it, many Sikhs would find it hard to keep their faith in a busy, secular society.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nSikhism also emphasises private devotion. Guru Ram Das describes the true Sikh rising early to meditate on the Name at home (Ang 305), and Nitnem prayers are usually said individually. A Sikh can meditate, live honestly (kirat karna) and share (vand chhakna) without going to the gurdwara.\n\nSome Sikhs live far from a gurdwara or are unable to attend because of illness or work. Many Sikhs today join online kirtan and keep a gutka (prayer book) at home. God is present everywhere, and mukti depends on grace and devotion, not on attendance.\n\nAlso, being in the sangat does not guarantee a religious life: a person can attend regularly but remain manmukh. What matters is the heart. A non-religious person might say community is valuable socially but not necessary for being a good person.\n\nCONCLUSION\n\nA Sikh can pray, meditate and live honestly alone, so the sangat is not strictly necessary for every part of religious life. But many core Sikh practices – langar, sewa, Amrit Sanskar and congregational worship – depend on it, and gurbani teaches that the satsangat helps the soul. The stronger view is that Sikhs need the sangat to live a full Sikh life, even though individual devotion is also essential.","evidence":["Ang 72","Ang 305","Guru Panth and gurmatta","Langar, Amrit Sanskar","Online kirtan"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"sangat evaluation"},{"id":"aqa-rs-a-sikhism-paper1-1-10-9","paper":"Beliefs","module":"1.10","moduleTitle":"The role and importance of the sangat (religious community)","question":"“The sangat is more important than the gurdwara building.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nFor Sikhs, what makes a place holy is the presence of the Guru Granth Sahib and of people remembering God's Name. Guru Nanak teaches that the true sangat is wherever the Name of the One God is spoken (Ang 72), not a particular building. A gurdwara can be a simple room, a house or even a tent.\n\nThe sangat carries the Guru's authority: Guru Gobind Singh gave authority to the Guru Panth as well as the Guru Granth Sahib. Decisions, initiation (through the Panj Pyare) and sewa are all done by people, not bricks.\n\nSikh history shows the sangat surviving without buildings – in times of persecution in the 18th century, Sikhs met in forests and camps. Today Sikhs gather for akhand paths in homes, and langar is served on streets for homeless people, showing that the community can act anywhere.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nThe gurdwara provides the conditions for the sangat to meet: a place to install the Guru Granth Sahib respectfully on the takht under the chanani, a langar hall and kitchen, and space for classes and community events. Without the building, many of these practices would be very difficult.\n\nHistoric gurdwaras such as the Harimandir Sahib are sacred because of their link to the Gurus. Many Sikhs feel a deep spiritual connection there, and the building's design, with four doors open to all, itself teaches equality.\n\nThe gurdwara also acts as a visible symbol of Sikh identity in Britain, a centre of community life and a refuge – the Nishan Sahib shows travellers they can find food and shelter. Some might say the two cannot really be separated: the building exists for the sangat, and the sangat needs a home.\n\nCONCLUSION\n\nThe gurdwara building is very valuable and some gurdwaras are deeply sacred because of their history. However, in Sikh teaching the holiness of a gurdwara comes from the Guru Granth Sahib and the sangat gathered there, not the building itself. So the sangat is more important, although the building is the normal and best place for it to gather.","evidence":["Ang 72","Guru Panth","18th-century persecution","Harimandir Sahib's four doors","Nishan Sahib"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"sangat vs building"}],"paper2":[{"id":"aqa-rs-a-sikhism-paper2-2-1-0","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"What is the takht in a gurdwara?\nA The flag outside the gurdwara\nB The raised platform or throne on which the Guru Granth Sahib is placed\nC The whisk waved over the scripture\nD The free kitchen","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B – The raised platform or throne on which the Guru Granth Sahib is placed. 'Takht' means throne, showing that the Guru Granth Sahib is treated as a living Guru, like a sovereign. The flag is the Nishan Sahib, the whisk is the chaur and the kitchen is the langar.","evidence":["Takht","Palki"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"takht"},{"id":"aqa-rs-a-sikhism-paper2-2-1-1","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Which one of the following is waved over the Guru Granth Sahib as a sign of respect and authority?\nA Chanani\nB Rumalla\nC Chaur\nD Manji","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C – Chaur (chaur sahib), a whisk usually made of yak hair or nylon set in a handle. In ancient India it was waved over royalty, so waving it over the Guru Granth Sahib shows its sovereign status. The chanani is the canopy, the rumalla the cloth covering and the manji the small bed/stand.","evidence":["Chaur sahib"],"examTip":"Read all four options before choosing. Only one is correct; write the letter clearly. If unsure, cross out options you know are wrong first.","answerTopic":"chaur"},{"id":"aqa-rs-a-sikhism-paper2-2-1-2","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Give one feature found outside a gurdwara.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: the Nishan Sahib (saffron/blue flag with the Khanda symbol, on a tall pole covered with cloth); a place to remove shoes; a place to wash hands (and sometimes feet); a sign/Khanda emblem; sometimes a pool (sarovar) at historic gurdwaras.","evidence":["Nishan Sahib"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"outside gurdwara"},{"id":"aqa-rs-a-sikhism-paper2-2-1-3","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Give one practice Sikhs carry out on entering the prayer hall of a gurdwara.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of: removing shoes; covering the head; washing hands; walking up to the Guru Granth Sahib and bowing/touching the forehead to the floor (matha tekna); making an offering of money or food; sitting on the floor (often men and women on different sides); not pointing feet towards the Guru Granth Sahib.","evidence":["Gurdwara etiquette"],"examTip":"A 1-mark short response needs one accurate, relevant point only. A short phrase or sentence is enough; do not waste time explaining.","answerTopic":"entering gurdwara"},{"id":"aqa-rs-a-sikhism-paper2-2-1-4","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Explain two ways in which the features of the gurdwara show respect for the Guru Granth Sahib.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: The Guru Granth Sahib rests on the takht or palki, a raised throne, under a chanani (canopy). Placing it higher than everyone else and under a canopy, like a king, shows Sikhs regard it as their living Guru.\n\nSecond way: The Guru Granth Sahib is covered with rumallas (decorated cloths) and the chaur is waved over it during reading. These are signs of royalty and care, and each night it is carried with ceremony (sukhasan) to its own room to rest, then opened again in the morning (prakash).","evidence":["Takht, palki, chanani","Rumalla, chaur","Prakash and sukhasan"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"respect for ggs"},{"id":"aqa-rs-a-sikhism-paper2-2-1-5","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Explain two different ways in which Sikhs show respect when visiting a gurdwara.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Through their appearance. All visitors, Sikh or not, cover their heads and remove their shoes, and no tobacco or alcohol is allowed. This shows humility before the Guru and treats the gurdwara as a holy place.\n\nSecond way: Through their actions before the Guru Granth Sahib. Sikhs walk up to the takht, bow and touch their forehead to the floor (matha tekna), often making an offering, and then sit on the floor without turning their back or feet towards the Guru. This shows the Guru Granth Sahib is the highest authority in their lives.","evidence":["Gurdwara etiquette","Matha tekna"],"examTip":"Give two separate ways. For each, make a simple point (1 mark) and then develop it with an example, consequence or detail (2 marks). Two undeveloped points score only 2.","answerTopic":"respect in gurdwara"},{"id":"aqa-rs-a-sikhism-paper2-2-1-6","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Explain two features of the gurdwara and their importance for Sikhs.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First feature: The palki and takht. The Guru Granth Sahib is placed on a raised platform (takht), often within a decorated canopied structure (palki), at the front of the diwan hall. Its importance is that it shows the scripture is the living Guru and sovereign, so all worship is directed towards it.\n\nSecond feature: The Nishan Sahib. This tall flagpole, covered in saffron cloth and topped with a Khanda, marks every gurdwara. It is important because it shows that the gurdwara is a place where anyone can find shelter, food and God's word, and it represents Sikh identity and the Khalsa.\n\nSource: Guru Gobind Singh declared before his death in 1708 that the Guru Granth Sahib would be the eternal Guru ('Guru Maniyo Granth'). This is why the scripture is enthroned like a ruler on the takht rather than kept on a shelf; the Sikh Rehat Maryada also instructs that it be installed on a clean, raised place under a canopy.","evidence":["'Guru Maniyo Granth' – Guru Gobind Singh, 1708","Sikh Rehat Maryada","Takht, palki, Nishan Sahib"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"gurdwara features"},{"id":"aqa-rs-a-sikhism-paper2-2-1-7","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"Explain two practices in the gurdwara associated with the Guru Granth Sahib.\nRefer to sacred writings or another source of Sikh belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First practice: Prakash and sukhasan. Each morning the Guru Granth Sahib is carried in procession, often on someone's head, from its resting room (sachkhand) to the takht and opened (prakash). In the evening it is closed and returned (sukhasan). This shows Sikhs treat the scripture with the honour due to a living Guru.\n\nSecond practice: Taking the hukamnama. After Ardas, the granthi opens the Guru Granth Sahib at random and reads the first hymn on the left-hand page. This is the Guru's 'order' or guidance for the day, which the sangat listens to and tries to follow.\n\nSource: Guru Gobind Singh's command that Sikhs should regard the Granth as Guru ('Sabh Sikhan ko hukam hai, Guru maniyo Granth') explains these practices. Because the Granth is the Guru, Sikhs wake it, put it to rest and seek its command each day, just as followers did with the human Gurus.","evidence":["'Guru maniyo Granth'","Prakash, sukhasan, sachkhand","Hukamnama"],"examTip":"Explain two teachings, each developed (2 + 2 marks), then name a source of Sikh authority AND apply it to the question (2 marks). Naming the Guru Granth Sahib with an Ang number, or a Guru's teaching, and showing how it supports your point is the safest way to get the source marks.","answerTopic":"ggs practices"},{"id":"aqa-rs-a-sikhism-paper2-2-1-8","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"“The palki and takht are the most important features of the gurdwara.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nThe palki and takht are where the Guru Granth Sahib is enthroned, and the Guru Granth Sahib is the living Guru. Without the scripture, a building would not be a gurdwara ('door of the Guru'). So the place where the Guru sits is the centre of the gurdwara and of all worship.\n\nEverything in the diwan hall is arranged around the takht: the sangat faces it, bows before it and sits lower than it. Rituals such as prakash, sukhasan, Ardas and the hukamnama all happen there. The chanani and chaur that surround it emphasise its royal status, showing the Guru's sovereignty over Sikhs' lives.\n\nGuru Gobind Singh told Sikhs to regard the Granth as Guru (1708), so honouring the Guru's throne is a direct response to his command.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Sikhs would say the langar is equally or more important because it expresses sewa and equality, two central Sikh beliefs. Gurdwaras without a langar are very rare, and it is often the part of the gurdwara most visible to non-Sikhs.\n\nOthers might argue that the Guru Granth Sahib itself is what matters, not the furniture. A takht or palki is only a symbol; the scripture could be honoured on any clean raised place. Focusing too much on decoration could risk the kind of ritualism Guru Nanak criticised.\n\nOthers again would point to the sangat – the gurdwara exists for the community to meet and remember God (Ang 72). The Nishan Sahib also has importance as a sign of welcome and shelter for all. A non-religious visitor might see the gurdwara's community role, such as food banks and classes, as most important.\n\nCONCLUSION\n\nThe palki and takht are the focal point of worship, because they hold the Guru Granth Sahib. But their importance comes entirely from the Guru they support. The best judgement is that the Guru Granth Sahib is the most important thing in the gurdwara, and the palki and takht are the most important features only because they express its status as Guru.","evidence":["'Guru maniyo Granth' (1708)","Takht, palki, chanani, chaur","Langar","Ang 72 – sangat","Nishan Sahib"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"palki takht evaluation"},{"id":"aqa-rs-a-sikhism-paper2-2-1-9","paper":"Practices","module":"2.1","moduleTitle":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","question":"“A gurdwara does not need decoration or special features.”\nEvaluate this statement.\nIn your answer you should:\n• refer to Sikh teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT\n\nGuru Nanak criticised religious show and ritual, teaching that truthful living is higher than outward displays (Ang 62). God is present everywhere, so a simple room where the Guru Granth Sahib is respectfully installed and the sangat meets is all that is needed.\n\nMoney spent on gold, marble and decoration could instead be used for sewa – feeding the poor or relieving disasters. Many Sikhs admire simple gurdwaras that put their resources into langar and charity.\n\nElaborate features may create pride (ahankar) or competition between gurdwaras, which feeds haumai rather than removing it. Humanists and other critics might also argue that expensive religious buildings are hard to justify when people are in poverty.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nThe special features of the gurdwara are not just decoration – they express beliefs. The takht, palki, chanani, chaur and rumallas show that the Guru Granth Sahib is the sovereign Guru, as Guru Gobind Singh commanded. Without them, it might be treated like an ordinary book.\n\nThe Nishan Sahib tells travellers and the community that food and shelter are available, and the langar hall makes sewa and equality possible. Many gurdwaras have four entrances, like the Harimandir Sahib, showing openness to all. These features teach Sikh beliefs visually.\n\nBeauty can inspire devotion. The Harimandir Sahib, covered in gold leaf by Maharaja Ranjit Singh, moves millions of pilgrims spiritually. Offering the best to the Guru can be an expression of love rather than pride.\n\nCONCLUSION\n\nStrictly, a gurdwara only needs the Guru Granth Sahib and the sangat; expensive decoration is not required and should never replace sewa. But features such as the takht, chanani, Nishan Sahib and langar are not mere decoration – they express respect for the Guru and Sikh values. So the statement is partly right about decoration, but wrong about special features, which most Sikhs see as important.","evidence":["Ang 62","'Guru maniyo Granth'","Harimandir Sahib – gold leaf under Maharaja Ranjit Singh","Nishan Sahib, langar","Humanist view"],"examTip":"Use the four bullets: refer to Sikh teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Develop each argument into a chain of reasoning (because... this means... therefore...). Up to 3 extra SPaG marks are available, so use specialist Punjabi terms accurately.","answerTopic":"gurdwara decoration"}]},"notes":[{"id":"aqa-rs-a-sikhism-paper1-1-1","paper":"Beliefs","module":"1.1","title":"The nature of God as expressed in the Mool Mantra","specFocus":"Spec 3.1.7.1 Key beliefs: the nature of God as expressed in the Mool Mantra – the content and significance of the Mool Mantra, Guru Granth Sahib (GGS) 1a.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"The Mool Mantra ('root verse') is the opening statement of the Guru Granth Sahib, at the top of Ang (page) 1, before Guru Nanak's Japji Sahib. Sikh tradition holds that Guru Nanak first spoke it after his experience of God at the river Bein in Sultanpur (c.1499), when he disappeared for three days and returned saying 'There is no Hindu, there is no Muslim'. Because it is the root of the scripture, it is recited daily in Nitnem, at the Amrit Sanskar and in many other ceremonies.\n\nCONTENT – each phrase explained\n• Ik Onkar – there is One God (the numeral 1 shows absolute oneness). The Ik Onkar symbol is found in gurdwaras, homes and on jewellery.\n• Satnam – God's name is Truth; God is eternal reality.\n• Karta Purakh – God is the Creator, the 'Creative Being'.\n• Nirbhau – without fear; nothing can threaten God.\n• Nirvair – without hatred or enmity; God has no enemies.\n• Akal Murat – timeless, immortal form; God is beyond time and death.\n• Ajuni – beyond birth; God is never born into any form, so Sikhs reject the idea of avatars.\n• Saibhang – self-existent; God depends on nothing.\n• Gurprasad – known by the Guru's grace; human effort alone cannot reach God.\nThe lines that follow (often recited with it) say God was 'True in the beginning, true through the ages, true now, and will be forever true'.\n\nSIGNIFICANCE\n1. It sums up Sikh belief about God – a 'creed' in a few words.\n2. It shapes ethics: if God is fearless and without hatred, Sikhs should try to live fearlessly and without hatred; if One God made all, all people are equal.\n3. It is used for nam japna (meditation on God's name), helping Sikhs overcome haumai.\n4. It marks belonging: the Panj Pyare recite it at Amrit Sanskar; some parents whisper it to a newborn.\n5. Many words are negative (without fear, without hatred, unborn), showing that God is beyond full human description – the Japji says God cannot be grasped by thinking, even a hundred thousand times (Ang 1).\n\nDIVERSITY OF VIEW\nSome Sikhs say the Mool Mantra ends at 'Gurprasad'; others include the following 'Jap… Aad sach' lines. All Sikhs agree it is the foundation of the scripture, though many stress it must be lived (truthful living, Ang 62), not just recited. Non-religious critics may say its claims cannot be proven.\n\nCONTEMPORARY EXAMPLE\nSikhs worldwide recite the Mool Mantra in the early morning (amrit vela) as part of Japji Sahib; gurdwaras in Britain often display Ik Onkar near the takht; Sikh charities such as Khalsa Aid express 'Nirvair' by helping people of all backgrounds without hatred.\n\nKEY TERMS: Mool Mantra, Ik Onkar, Satnam, Karta Purakh, Nirbhau, Nirvair, Akal Murat, Ajuni, Saibhang, Gurprasad, Ang, Nitnem, Japji Sahib."},{"id":"aqa-rs-a-sikhism-paper1-1-2","paper":"Beliefs","module":"1.2","title":"God as Creator: God in and through the universe, and separate from it","specFocus":"Spec 3.1.7.1 Key beliefs: God as Creator, including different aspects of God's relationship with creation – God shown in and through the universe; God as separate from the universe.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"God as Karta Purakh (Creator) is one of the first ideas in the Mool Mantra. Sikhs believe that God created the universe out of God's own will, without using any pre-existing material, and continues to sustain it.\n\nHOW GOD CREATED\n• Before creation, there was only God. Guru Nanak's Maru Solhe (Ang 1035) describes 'endless ages of utter darkness' with no earth, sky, day, night, sun or moon – only God's hukam (command) and God in deep meditation (sunn samadh).\n• God then created by a single word: 'You created the vast expanse of the universe with One Word, and hundreds of thousands of rivers began to flow' (Japji pauri 16, Ang 3).\n• Only God knows when creation happened (Japji pauri 21, Ang 4). The Guru Granth Sahib describes countless worlds, skies and galaxies (Japji pauri 22, Ang 5), which many Sikhs see as consistent with modern science.\n• God can also bring creation back into God's self; creation and dissolution happen in cycles according to hukam.\n\nTWO ASPECTS OF GOD'S RELATIONSHIP WITH CREATION\n1. God shown in and through the universe – IMMANENT, sometimes called SARGUN ('with qualities'). God's light (jot) is in every part of creation: 'Among all is the Light – You are that Light' (Ang 13). Guru Nanak wrote 'I am a sacrifice to Your creation (kudrat); You are pervading it' (Ang 469). So nature and people reveal God.\n2. God as separate from the universe – TRANSCENDENT, NIRGUN ('without qualities'). God existed before creation, is beyond time (Akal) and space, and cannot be contained or fully described by anything created. God is not the same as the universe.\nSikhs hold both together: God is in everything but also infinitely greater than everything. This is sometimes compared to an artist present in a painting but not limited to it.\n\nCONSEQUENCES FOR SIKH LIFE\n• Respect for nature – environmental care is a religious duty. EcoSikh and Sikh Environment Day (14 March, linked to Guru Har Rai's love of nature) encourage tree-planting and green gurdwaras.\n• Respect for all people, since God's light is in all.\n• Humility and gratitude, and acceptance of hukam – God's order.\n• Maya: the created world is real but temporary; attachment to it (moh) is a barrier to mukti.\n\nDIVERSITY OF VIEW\nMost Sikhs see science (Big Bang, evolution) as compatible with gurbani; a few interpret scripture more literally. Some Sikhs emphasise the nirgun God of meditation, others the sargun God seen in the Gurus' teaching and nature. Atheists and humanists argue science explains the universe without God.\n\nKEY TERMS: Karta Purakh, hukam, kudrat, jot, sargun, nirgun, immanent, transcendent, maya, Ang."},{"id":"aqa-rs-a-sikhism-paper1-1-3","paper":"Beliefs","module":"1.3","title":"The nature of human life as an opportunity to unite with God, and the Sikh virtues","specFocus":"Spec 3.1.7.1 Key beliefs: the nature of human life as an opportunity to unite with God, including the development of Sikh virtues such as wisdom, truthful living, justice, temperance, self-control, patience, courage, humility, contentment.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"HUMAN LIFE AS AN OPPORTUNITY\nSikhs believe every living being has a soul (atma) containing a spark of God's light (jot). Souls pass through many life forms – the Guru Granth Sahib speaks of wandering through 8.4 million (chaurasi lakh) life forms – according to karma. Human birth is rare and precious because only humans can consciously remember God and so reach mukti (liberation, union with God). Guru Arjan writes in the Sohila: 'This human body has been given to you. This is your chance to meet the Lord of the Universe. Nothing else will work' (Ang 12). Life is therefore not to be wasted on maya (illusion) and the pursuit of wealth, pleasure or status.\n\nHOW A SIKH USES THIS OPPORTUNITY\n• Nam japna – remembering and meditating on God's Name.\n• Kirat karna – honest work.\n• Vand chhakna – sharing with others; sewa.\n• Developing virtues and overcoming haumai and the five thieves.\n\nTHE SIKH VIRTUES (spec list)\n• Wisdom (gian) – spiritual understanding gained from the Guru's teaching, not just knowledge.\n• Truthful living (sach aachaar) – 'Truth is higher than everything, but higher still is truthful living' (Ang 62). Includes honesty in work.\n• Justice (niaon) – standing up for the oppressed; the Khalsa was formed partly to defend justice.\n• Temperance – moderation; avoiding excess, intoxicants (alcohol, tobacco, drugs are forbidden for amritdhari Sikhs).\n• Self-control – mastering the five thieves, e.g. lust and anger.\n• Patience (dhiraj/sabr) – accepting God's hukam calmly in hardship.\n• Courage (bravery) – shown by the Gurus' martyrdom and Sikh history; linked to God as Nirbhau (fearless).\n• Humility (nimrata) – the opposite of haumai: 'Sweetness and humility are the essence of goodness and virtue' (Ang 470).\n• Contentment (santokh) – satisfaction with what God gives; the opposite of greed.\nSikh writers also commonly list five virtues: sat (truth), santokh (contentment), daya (compassion), nimrata (humility) and pyare (love).\n\nWHY THE VIRTUES MATTER\nVirtues reflect God's qualities (e.g. Nirbhau, Nirvair), so developing them makes a person gurmukh (God-centred). They are not earned by effort alone: Sikhs believe they grow through God's grace (nadar) and meditation.\n\nDIVERSITY AND EXAMPLES\nSome Sikhs stress inner meditation, others active service and justice; most see them as inseparable. Examples today: Sikh volunteers running langar for the homeless in UK cities, or Sikhs speaking out against injustice, show virtues of compassion, justice and courage.\n\nKEY TERMS: atma, jot, mukti, maya, gian, sach aachaar, nimrata, santokh, daya, nadar, gurmukh."},{"id":"aqa-rs-a-sikhism-paper1-1-4","paper":"Beliefs","module":"1.4","title":"Karma, rebirth and the aim of mukti","specFocus":"Spec 3.1.7.1 Key beliefs: beliefs in karma and rebirth, and the aim of mukti; the meaning of mukti, including the different aspects of mukti – positive and negative.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"KARMA\nKarma means 'action' and the law of cause and effect. Every action has consequences, in this life and beyond. Japji Sahib says 'You shall harvest what you plant' ('Aape beej aape hi khaahu', pauri 20, Ang 4). Good actions bring spiritual progress; selfish actions driven by haumai and the five thieves bring suffering and further births.\n\nREBIRTH (transmigration / samsara)\nThe soul (atma) is eternal and passes from body to body. The Guru Granth Sahib speaks of the soul wandering through 8.4 million (chaurasi lakh) life forms. Karma decides the body one is born into: 'By the karma of past actions, the robe of this physical body is obtained; by God's grace, the gate of liberation is found' (Japji pauri 4, Ang 2). Human birth is rare and is the opportunity to escape the cycle (Ang 12).\n\nGRACE AND KARMA\nUnlike some ideas of karma as a fixed machine, Sikhism teaches that God's grace (nadar, kirpa, Gurprasad) can overcome karma. Meditation on the Name, the Guru's teaching and the sangat help wash away the effects of past karma. Karma explains the body we have; grace opens the door to mukti.\n\nMUKTI – THE AIM OF LIFE\nMukti means liberation. It has two aspects:\n• NEGATIVE aspect – what one is freed FROM: the cycle of birth, death and rebirth; the bondage of karma; haumai, maya and the five thieves (lust, anger, greed, attachment, pride).\n• POSITIVE aspect – what one gains: union with God, merging with God's light like a drop of water with the ocean; living in God's presence and bliss (anand); reaching Sach Khand (realm of truth, Japji pauri 37, Ang 8).\n\nJIVAN MUKTI\nSikhs believe mukti can be achieved while still alive (jivan mukt). A jivan mukt person lives in the world as a householder, but free from ego, constantly remembering God and serving others. This makes mukti something that shapes everyday life, not just life after death.\n\nHOW TO ACHIEVE MUKTI\nGrace of God; nam japna; becoming gurmukh; sewa; kirat karna; vand chhakna; the company of the sangat; progressing through the five khands.\n\nDIVERSITY\nSikhs differ on how literally to take the 8.4 million life forms and heaven/hell imagery – some see them as real states, others as symbolic of a soul's closeness or distance from God. Humanists reject rebirth, arguing this is our only life; some critics argue karma can be misused to justify inequality, which the Gurus opposed.\n\nKEY TERMS: karma, atma, samsara/transmigration, chaurasi lakh, nadar, Gurprasad, mukti, jivan mukti, Sach Khand, anand."},{"id":"aqa-rs-a-sikhism-paper1-1-5","paper":"Beliefs","module":"1.5","title":"The five stages of liberation (five khands) and the barriers to mukti","specFocus":"Spec 3.1.7.1 Key beliefs: the five stages of liberation (five khands) and barriers to mukti (illusion, self-centredness, lust, anger, greed, worldly attachment, pride).","sourcePages":"Written to match the published AQA GCSE specification.","summary":"THE FIVE KHANDS (realms or stages of spiritual development)\nGuru Nanak describes five stages on the path to mukti at the end of Japji Sahib (pauris 34–37, Ang 7–8). Many Sikhs see them as stages of inner growth rather than physical places.\n1. Dharam Khand – realm of duty/righteousness. God made the earth 'as a home for dharam' (dharamsaal). People realise that their actions are judged and accept moral responsibility.\n2. Gian Khand – realm of knowledge. The person gains spiritual knowledge, wondering at the vastness of creation – countless worlds, suns and moons.\n3. Saram Khand – realm of effort (sometimes 'spiritual endeavour' or beauty). The mind and intellect are refined and shaped by effort in meditation and good living.\n4. Karam Khand – realm of grace. God's grace fills the person with spiritual power; here dwell the great devotees who have overcome haumai. 'In the realm of grace, the Word is power' (Ang 8).\n5. Sach Khand – realm of truth: 'In the realm of truth the Formless Lord abides' (Ang 8). The soul is united with God – mukti. Guru Nanak says describing it is 'as hard as steel'.\nNotice: effort comes first, but the final stages depend on grace.\n\nBARRIERS TO MUKTI\n• Maya – illusion: treating the temporary world (wealth, status, pleasures) as if it were ultimate reality, and forgetting God.\n• Haumai – self-centredness/ego: the root barrier (see module 1.6).\n• The five thieves (panj chor), which grow from haumai:\n – Kaam – lust; overcome by self-control.\n – Krodh – anger; overcome by patience and forgiveness.\n – Lobh – greed; overcome by contentment (santokh) and sharing.\n – Moh – worldly attachment (to possessions, people, status); overcome by detachment while still living as a householder.\n – Ahankar – pride; overcome by humility (nimrata).\nGurbani describes these thieves breaking into the 'house' of the body. The remedy is nam japna, the Guru's teaching, sewa, the sangat and God's grace.\n\nLIVING THIS OUT\nSikhs do not withdraw from the world to escape maya; they live as householders but try to be 'like a lotus in water' – in the world but not stained by it. Practices such as giving dasvandh, sewa and avoiding intoxicants and adultery (Amrit vows) help guard against the thieves.\n\nDIVERSITY\nSome Sikhs read the khands as literal realms; others as psychological stages. There is debate on whether Sach Khand can be reached in this life (jivan mukti) or only after death. Non-religious people may agree that greed, anger and pride are harmful, without linking them to mukti.\n\nKEY TERMS: khand, Dharam/Gian/Saram/Karam/Sach Khand, maya, haumai, panj chor, kaam, krodh, lobh, moh, ahankar."},{"id":"aqa-rs-a-sikhism-paper1-1-6","paper":"Beliefs","module":"1.6","title":"Being gurmukh rather than manmukh, and the elimination of haumai","specFocus":"Spec 3.1.7.1 Key beliefs: the importance of being gurmukh (God-centred) rather than manmukh (man-centred) and the elimination of pride or ego (haumai).","sourcePages":"Written to match the published AQA GCSE specification.","summary":"GURMUKH AND MANMUKH\n• Gurmukh – literally 'facing the Guru'. A gurmukh is God-centred: they live by the Guru's teaching, constantly remember God's Name (simran), accept God's will (hukam) and develop virtues such as humility, contentment and compassion. They see God's light in all people and serve them. The gurmukh is the ideal Sikh and is moving towards mukti.\n• Manmukh – literally 'facing one's own mind'. A manmukh is self-centred: they follow their own desires, are ruled by haumai and the five thieves (lust, anger, greed, attachment, pride), are attached to maya and forget God. They may be religious outwardly, but their heart is not turned to God. They remain in the cycle of rebirth and are restless and unsatisfied.\nThe Guru Granth Sahib contrasts the two repeatedly, for example in Guru Nanak's Siddh Gosht (Ang 938–946), where he explains to yogis that it is by becoming gurmukh, not by leaving society, that God is found.\n\nHAUMAI (ego, self-centredness)\n• Haumai means 'I, I' – the sense of self as separate from God and from others, putting 'me' first.\n• It is the root barrier to mukti; the five thieves grow from it.\n• 'Haumai is a chronic disease, but it also contains its own cure' (Guru Angad, Asa di Var, Ang 466). The cure is turning the self towards God.\n\nHOW HAUMAI IS ELIMINATED\n1. Nam japna / simran – meditating on 'Waheguru' and the Mool Mantra.\n2. Following gurbani – reading or hearing the Guru Granth Sahib, taking a daily hukamnama.\n3. Sewa – humble service, e.g. washing dishes, cleaning shoes, cooking langar.\n4. Sangat – the support of the community.\n5. Humility in worship – covering the head, bowing, sitting on the floor.\n6. God's grace (nadar) – ultimately haumai is removed by God's gift.\n7. Amrit Sanskar – the initiate symbolically gives up their old self and caste identity.\n\nWHY IT MATTERS\nBeing gurmukh is the path to jivan mukti and union with God; it also transforms relationships – a gurmukh treats others equally and lives honestly (kirat karna) and generously (vand chhakna).\n\nDIVERSITY\nSome Sikhs stress the inner, meditative side of being gurmukh; others the outward Khalsa discipline (five Ks, rehat). Some argue haumai can be completely eliminated (as in the Gurus); others that it is a lifelong struggle. Humanists value self-esteem and may see some 'ego' as healthy.\n\nCONTEMPORARY EXAMPLE\nVolunteers at the langar in British gurdwaras – including professionals such as doctors and lawyers – wash pots and serve food alongside others, deliberately setting aside status to reduce haumai.\n\nKEY TERMS: gurmukh, manmukh, haumai, simran, hukam, hukamnama, nadar, sewa, sangat."},{"id":"aqa-rs-a-sikhism-paper1-1-7","paper":"Beliefs","module":"1.7","title":"The oneness of humanity and the equality of all, including the equality of women with men","specFocus":"Spec 3.1.7.1 Beliefs about the nature of human life: belief in the oneness of humanity and in the equality of all, including complete equality of women with men.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"THE ONENESS OF HUMANITY\nSikhs believe that all humans come from the One God (Ik Onkar) and that God's light (jot) shines in every person. Humanity is therefore one family:\n• 'The One God is our father; we are the children of the One' (Guru Arjan, Ang 611).\n• 'From the One Light, the entire universe welled up; so who is good and who is bad?' (Bhagat Kabir, Ang 1349–50).\n• 'No one is my enemy and no one is a stranger; I get along with everyone' (Guru Arjan, Ang 1299).\n• Guru Gobind Singh wrote 'Recognise the whole human race as one' ('Manas kee jaat sabhai ekai pahchaanbo') – in the Akal Ustat in the Dasam Granth (not the Guru Granth Sahib).\n\nEQUALITY OF ALL\n• Caste (jati) is rejected: 'Recognise the Lord's Light within all, and do not ask about caste; there is no caste in the world hereafter' (Ang 349).\n• Religion: Guru Nanak's first teaching after the river Bein was 'There is no Hindu, there is no Muslim' – meaning all are equally God's people. The Guru Granth Sahib includes hymns of Hindu and Muslim saints.\n• Wealth and status: rich and poor sit together in the sangat and langar.\n\nCOMPLETE EQUALITY OF WOMEN WITH MEN\n• Spiritual equality – women have the same soul and light and can attain mukti.\n• Guru Nanak: 'From woman, man is born… So why call her inferior? From her, kings are born' (Asa di Var, Ang 473).\n• Guru Amar Das spoke against sati (widow-burning) and purdah (veiling/seclusion) and appointed women as well as men to teach and lead communities.\n• The Sikh Rehat Maryada allows women to take part in every religious function: reading the Guru Granth Sahib, kirtan, Ardas, serving as granthi; women take amrit and are named Kaur.\n• Role models: Mata Khivi (langar), Mata Gujri, Mata Sahib Kaur (mother of the Khalsa), Mai Bhago (warrior, 1705).\n\nDIVERSITY / CONTEMPORARY ISSUES\n• Practice does not always match teaching: some gurdwaras are associated with particular caste groups (e.g. Ramgarhia gurdwaras in the UK); some families still face cultural pressures such as son-preference or dowry.\n• Debate about women serving as Panj Pyare and performing kirtan at the Harimandir Sahib.\n• Bibi Jagir Kaur became the first woman president of the SGPC in 1999.\n• Many Sikhs campaign against gender discrimination, citing Ang 473.\n\nWHY IT MATTERS\nEquality affects worship (everyone covers heads and sits on the floor), langar, sewa, attitudes to other faiths and social justice.\n\nKEY TERMS: Ik Onkar, jot, jati (caste), sangat, langar, Kaur, Sikh Rehat Maryada, sati, purdah."},{"id":"aqa-rs-a-sikhism-paper1-1-8","paper":"Beliefs","module":"1.8","title":"The expression of the equality of all: the lives of the Gurus, the Guru Granth Sahib and Sikhism today","specFocus":"Spec 3.1.7.1 Beliefs about the nature of human life: the expression of the equality of all in the stories of the lives of the Gurus, including Guru Nanak and Guru Gobind Singh; the Guru Granth Sahib; in Sikhism today.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"IN THE LIVES OF THE GURUS\nGuru Nanak (1469–1539)\n• After his experience at the river Bein he declared 'There is no Hindu, there is no Muslim' – all are equal before God.\n• His lifelong companion was Bhai Mardana, a Muslim musician.\n• Bhai Lalo and Malik Bhago: Guru Nanak stayed with Lalo, a poor carpenter of a 'low' caste, rather than accepting a feast from Malik Bhago, a rich official who exploited the poor. When he squeezed Lalo's bread, milk came out; Bhago's food produced blood – honest earnings are pure, exploitation is not.\n• He began the practice of shared meals at Kartarpur, the community he founded.\n• He spoke for women: 'Why call her inferior? From her, kings are born' (Ang 473).\nOther Gurus: Guru Angad and Mata Khivi developed the langar (Mata Khivi is praised at Ang 967); Guru Amar Das insisted 'first the langar, then the Guru' – even the Mughal Emperor Akbar ate on the floor with everyone – and opposed sati and purdah.\nGuru Gobind Singh (1666–1708)\n• At Vaisakhi 1699 he called for volunteers willing to give their heads. Five came forward from different castes and regions – the Panj Pyare.\n• All initiates drank amrit from one iron bowl, ending caste distinctions within the Khalsa.\n• Men were named Singh, women Kaur, replacing caste-based surnames.\n• He then knelt and asked the Panj Pyare to initiate him – the Guru and his followers equal.\n• In the Akal Ustat (Dasam Granth) he wrote 'Recognise the whole human race as one'.\n\nIN THE GURU GRANTH SAHIB\n• Compiled by Guru Arjan (Adi Granth, 1604) and completed by Guru Gobind Singh; contains hymns by six Gurus and by Hindu and Muslim saints (bhagats) of many castes – Kabir (weaver), Ravidas (leather-worker), Namdev (calico printer), Sain (barber), Sheikh Farid (Muslim Sufi).\n• Its teachings reject caste (Ang 349) and affirm women (Ang 473) and the unity of humanity (Ang 611, Ang 1349).\n• It is written in Gurmukhi, open to all to read.\n\nIN SIKHISM TODAY\n• Langar in every gurdwara; at the Harimandir Sahib tens of thousands are fed every day.\n• Equal right of women to every religious role (Sikh Rehat Maryada).\n• Use of Singh and Kaur; one bowl at Amrit Sanskar.\n• Sewa to all, e.g. Khalsa Aid, street langar for homeless people in British cities.\n• Challenges: caste-linked gurdwaras and marriage preferences in some communities; debates about women as Panj Pyare and in kirtan at the Harimandir Sahib.\n\nKEY TERMS: Panj Pyare, Khalsa, langar, pangat, bhagat bani, Adi Granth, Singh, Kaur."},{"id":"aqa-rs-a-sikhism-paper1-1-9","paper":"Beliefs","module":"1.9","title":"Sewa: the importance and priority of service to others","specFocus":"Spec 3.1.7.1 Beliefs about the nature of human life: sewa – the importance and priority of service to others, including physical (tan), mental (man) and material (dhan).","sourcePages":"Written to match the published AQA GCSE specification.","summary":"WHAT IS SEWA?\nSewa (seva) means selfless service to others, done without seeking reward or praise (nishkam sewa). Sikhs see it as service to God, because God's light (jot) is in every person. It is one of the most visible features of Sikh life and an essential part of being gurmukh.\n\nKEY TEACHINGS\n• 'In the midst of this world, do sewa, and you shall be given a place of honour in the Court of the Lord' (Guru Nanak, Sri Rag, Ang 26).\n• Sewa overcomes haumai: humble service, such as cleaning shoes or washing dishes, breaks down pride.\n• It expresses equality: when anyone may serve and anyone may be served, status disappears.\n• It is linked to the three pillars: nam japna (remembering God), kirat karna (honest work) and vand chhakna (sharing).\n\nTHREE TYPES OF SEWA\n1. Tan sewa – physical service using the body: cooking, serving and cleaning in the langar; cleaning the gurdwara; looking after shoes; helping at disasters; caring for the sick.\n2. Man sewa – mental service using the mind, knowledge and skills: teaching Punjabi, gurbani or kirtan; giving advice or counselling; doing professional work, such as medical or legal help, without charge; studying scripture to share it.\n3. Dhan sewa – material service using money and possessions: giving dasvandh (a tenth of income), donating food to the langar, funding charities and gurdwaras.\n\nEXAMPLES FROM SIKH HISTORY\n• Guru Amar Das served Guru Angad humbly for years, including fetching water before dawn, before becoming the third Guru.\n• Mata Khivi ran the langar with Guru Angad (praised at Ang 967).\n• Bhai Kanhaiya gave water to injured soldiers of both armies at Anandpur; Guru Gobind Singh praised him for seeing God in all and gave him ointment to treat their wounds. He is an inspiration for Sikh humanitarian work.\n\nPRIORITY OF SEWA\nSewa is not an optional extra – it is part of worship itself. Many Sikhs see it as one of the most important ways to show love for God. However, Sikhs teach that sewa should come from remembrance of God; sewa done for show increases haumai.\n\nSEWA TODAY\n• Langar in gurdwaras every day.\n• Khalsa Aid (founded 1999) – disaster relief worldwide, including refugee camps and earthquake zones.\n• Street langar and food banks for homeless people in UK cities; during COVID-19 many gurdwaras delivered meals to NHS staff and vulnerable people.\n• Blood-donation drives and environmental sewa (EcoSikh).\n\nDIVERSITY\nSikhs agree on the importance of sewa but may emphasise different types; some say tan sewa is most humbling, others that dhan sewa helps most people. Some debate whether sewa should be directed mainly to the Sikh community or equally to all (most say all).\n\nKEY TERMS: sewa, nishkam, tan, man, dhan, dasvandh, vand chhakna, kirat karna, langar."},{"id":"aqa-rs-a-sikhism-paper1-1-10","paper":"Beliefs","module":"1.10","title":"The role and importance of the sangat (religious community)","specFocus":"Spec 3.1.7.1 Beliefs about the nature of human life: the role and importance of the sangat (religious community).","sourcePages":"Written to match the published AQA GCSE specification.","summary":"MEANING\nSangat means 'company' or 'association'. It refers to the Sikh religious community, especially the congregation gathered in the presence of the Guru Granth Sahib. The ideal is the satsangat – 'true company' – of people who remember God. 'How is the Society of the Saints to be known? There, the Name of the One Lord is chanted' (Guru Nanak, Ang 72).\n\nTHE SANGAT'S SPIRITUAL ROLE\n• Shared worship: kirtan (singing hymns), katha (explanation), Ardas (congregational prayer) and hukamnama. Many Sikhs find the mind settles on God more easily in the sangat.\n• Overcoming haumai: being part of a humble, serving community helps the individual become gurmukh. Good company is said to shape the soul, just as bad company leads to the five thieves.\n• Guru Panth: Guru Gobind Singh gave the Guru's authority to the scripture (Guru Granth) and to the community of the Khalsa (Guru Panth). The sangat can make collective decisions (gurmatta), and the Panj Pyare who conduct Amrit Sanskar are chosen from it. Sikhs often say the Guru is present where five Sikhs gather in faith.\n\nTHE SANGAT'S PRACTICAL ROLE\n• Sewa and langar – the sangat cooks, serves and cleans.\n• Equality – everyone sits on the floor; there is no priestly caste; anyone may read or perform kirtan.\n• Support – care for the sick, the bereaved and newcomers; marriage (Anand Karaj) and naming ceremonies take place before the sangat.\n• Education – Punjabi, gurbani and kirtan classes, youth camps.\n• Identity – helping Sikhs in Britain keep their faith and culture.\n\nHISTORY\nGuru Nanak formed the first sangat at Kartarpur, where people lived, worked, worshipped and ate together. Later Gurus set up sangats across India. In the 18th century, when Sikhs were persecuted, the Sarbat Khalsa (gathering of the whole Khalsa) met at the Akal Takht to make decisions.\n\nDIVERSITY\n• Some Sikhs attend the gurdwara daily; others mainly at weekends or festivals; some rely on prayer at home and online kirtan.\n• Sangats sometimes divide along lines of caste, politics or tradition (e.g. separate Ramgarhia or other caste-linked gurdwaras), which many Sikhs criticise as against the Gurus' teaching.\n• Non-religious people may value community but not its spiritual authority.\n\nCONTEMPORARY EXAMPLE\nIn the UK, sangats in places such as Southall and Birmingham run food banks, youth clubs and support for elderly people, as well as weekly diwan (worship).\n\nKEY TERMS: sangat, satsangat, Guru Panth, gurmatta, kirtan, katha, Ardas, diwan, Sarbat Khalsa."},{"id":"aqa-rs-a-sikhism-paper2-2-1","paper":"Practices","module":"2.1","title":"Religious features of the gurdwara: design, furniture and artefacts, including the palki and takht","specFocus":"Spec 3.1.7.2 Worship and service: religious features of the gurdwara – design, furniture and artefacts; the practices associated with these features and their importance, including the palki and takht.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"MEANING\nGurdwara means 'door' or 'gateway to the Guru'. Any building becomes a gurdwara when the Guru Granth Sahib is installed in it. Gurdwaras range from converted houses or churches in Britain to great historic shrines in India.\n\nOUTSIDE\n• Nishan Sahib – tall flagpole covered in saffron cloth (chola), with a triangular saffron or blue flag bearing the Khanda; shows that the gurdwara is a place of refuge, food and God's word. The cloth is renewed each Vaisakhi.\n• Shoe area and washing facilities – visitors remove shoes and wash hands.\n• Many gurdwaras have four doors or entrances (as at the Harimandir Sahib), showing welcome to people from all directions and backgrounds.\n\nTHE DIWAN HALL (prayer hall)\n• Takht – a raised platform or 'throne' at the front on which the Guru Granth Sahib is placed. It is higher than the sangat, showing the scripture's authority as Guru.\n• Palki – a decorated, canopied structure (often like a small palace) on the takht, in which the Guru Granth Sahib is enthroned; 'palki' also refers to the palanquin used to carry the scripture in procession. Shows the Guru's royal status.\n• Manji sahib – small cushioned stand/bed on which the Guru Granth Sahib actually rests.\n• Chanani – canopy above the scripture, a traditional sign of honour for royalty.\n• Rumallas – rich cloths covering the Guru Granth Sahib when not being read; families often offer one at naming or wedding ceremonies.\n• Chaur (chaur sahib) – whisk waved over the scripture during reading, a sign of sovereignty and respect.\n• Golak – box for offerings.\n• No chairs: the sangat sits on the carpeted floor, often men and women on different sides, showing equality and humility. No images or idols.\n• Raagis (musicians) sit on a platform to perform kirtan with harmonium and tabla.\n• Sachkhand – a separate room where the Guru Granth Sahib is laid to rest at night.\n\nPRACTICES LINKED TO THESE FEATURES\n• Prakash – the Guru Granth Sahib is carried (often on the head) to the takht and opened each morning; sukhasan – closed and returned to the sachkhand at night.\n• Matha tekna – bowing before the Guru Granth Sahib and making an offering.\n• Granthi – reads and looks after the scripture; anyone trained, male or female, may do this.\n• Hukamnama – a random reading taken as the Guru's command for the day.\n• Karah prasad – sweet blessed food given to all, a sign of God's grace and equality.\n• Langar hall – free kitchen (see 2.5).\n\nIMPORTANCE\nThe features express Guru Gobind Singh's command (1708) that the Granth is the eternal Guru. The scripture is treated as a living sovereign, which focuses worship on God's word. Equality is shown by floor seating, karah prasad and langar.\n\nDIVERSITY\nSome gurdwaras are very ornate, others simple; some Sikhs think money is better spent on sewa. Practice varies on seating (some gurdwaras do not separate men and women).\n\nKEY TERMS: gurdwara, Nishan Sahib, Khanda, diwan hall, takht, palki, manji sahib, chanani, rumalla, chaur, golak, sachkhand, prakash, sukhasan, karah prasad."}],"rubrics":{"Beliefs":{"1":"1 mark. Either a multiple-choice question (choose the one correct option from A–D) or a short-response 'Give one…' question. One accurate, relevant answer earns the mark; no explanation is needed. AO1:1 knowledge.","12":"12 marks (AO2) plus up to 3 SPaG marks. 'Evaluate this statement' – refer to Sikh teaching, give reasoned arguments for the statement and for a different view, reach a justified conclusion. Levels: L4 (10–12) well-argued, reasoned consideration of different views, logical chains of reasoning leading to judgements supported by relevant knowledge, religion applied to the issue; L3 (7–9) reasoned consideration of different views, logical chains of reasoning, clear reference to religion; L2 (4–6) reasoned consideration of one view, or recognition of different views each with reasons (max L2 with no reference to religion); L1 (1–3) a point of view with reason(s) stated.","4":"4 marks (AO1:2 influence). Typically 'Explain two ways in which belief in … influences Sikhs today.' For each way: simple explanation of a relevant and accurate influence = 1 mark; detailed (developed) explanation = 2 marks. Two ways × 2 marks.","6":"6 marks (AO1:1). 'Explain two Sikh teachings about … Refer to sacred writings or another source of Sikh belief and teaching in your answer.' Each teaching: simple explanation 1 mark, detailed explanation 2 marks (max 4). Source of authority: 2 marks for naming a relevant source AND applying it to the question; 1 mark for naming it only, or for applying it without naming it."},"Practices":{"1":"1 mark. Either a multiple-choice question (choose the one correct option from A–D) or a short-response 'Give one…' question. One accurate, relevant answer earns the mark; no explanation is needed. AO1:1 knowledge.","12":"12 marks (AO2) plus up to 3 SPaG marks. 'Evaluate this statement' – refer to Sikh teaching, give reasoned arguments for the statement and for a different view, reach a justified conclusion. Levels: L4 (10–12) well-argued, reasoned consideration of different views, logical chains of reasoning leading to judgements supported by relevant knowledge, religion applied to the issue; L3 (7–9) reasoned consideration of different views, logical chains, clear reference to religion; L2 (4–6) reasoned consideration of one view, or different views each with reasons (max L2 with no reference to religion); L1 (1–3) a point of view with reason(s) stated.","4":"4 marks (AO1:2/AO1:3). Typically 'Explain two different ways in which Sikhs …' or 'Explain two ways in which … influences Sikhs today.' For each way: simple explanation 1 mark; detailed explanation 2 marks. Where 'different' is asked, the two ways must genuinely differ.","6":"6 marks (AO1:1). 'Explain two … Refer to sacred writings or another source of Sikh belief and teaching in your answer.' Each point: simple explanation 1 mark, detailed explanation 2 marks (max 4). Source of authority: 2 marks for naming a relevant source AND applying it to the question; 1 mark for naming only, or applying without naming."}},"markingSchema":{"dsl":"SCHEME AQA Religious Studies adaptable guidance\nCOMMAND ALL\nMARKS AUTO\nREQUIRE use accurate subject knowledge and answer the command word\nREQUIRE support religious or non-religious views where the question asks for them\nNEVER invent quotations, sources or official level descriptors\nFEEDBACK be specific, supportive and honest about missing content\n\nCOMMAND Explain\nMARKS AUTO\nAWARD 1 one accurate relevant point\nAWARD 1 a clear linked explanation\n\nCOMMAND Evaluate\nMARKS AUTO\nBAND 9-12 well-argued evaluation with a justified conclusion\nBAND 5-8 relevant discussion with some evaluation\nBAND 1-4 limited points with little evaluation","id":"aqa-rs-generic","references":[{"title":"AQA Religious Studies 8062 specification","url":"https://www.aqa.org.uk/subjects/religious-studies/gcse/religious-studies-8062/specification"},{"title":"AQA scheme of assessment","url":"https://www.aqa.org.uk/subjects/religious-studies/gcse/religious-studies-8062/specification/scheme-of-assessment"}],"sourceNotes":"AQA GCSE RS A uses 1/1/4/6/12 question structures and a separate SPaG overlay. Check the current official specification and mark scheme before relying on a mark estimate.","status":"adaptable","title":"AQA Religious Studies · check and adapt","version":1},"moduleCounts":{"paper1":10,"paper2":1},"meta":{"modulesTotal":11,"paper1QuestionCount":100,"paper2QuestionCount":10,"provenance":"Original practice questions, revision notes and indicative model answers written to the published AQA GCSE Religious Studies A (8062) specification (subject content 3.1.7 Sikhism; scheme of assessment v1.3, five-part questions of 1, 1, 4, 6 and 12 marks from summer 2026). Not past-paper material and not copied from AQA mark schemes, textbooks or revision guides. Model answers are indicative exemplars, not official mark schemes. Short quotations from the Guru Granth Sahib (cited by Ang/page) and other Sikh sources are used for study purposes; English renderings are paraphrased translations.","qualification":"AQA GCSE Religious Studies A (8062), Component 1: The study of religions – Sikhism (3.1.7)","questionTotal":110,"title":"AQA GCSE Religious Studies A: Sikhism"}});
